"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import type { EntradaArtista, EntradaEditarArtista, ResultadoGestao } from "@/modules/artists";
import { CampoAdmin, FormularioAdmin, classeCampo, texto, useGestao } from "./formulario";

type Artista = {
  id: string;
  userId: string;
  nome: string;
  email: string;
  telefone: string;
  slug: string;
  bio: string | null;
  avatarUrl: string | null;
  instagram: string | null;
  estilos: string[];
};
type Props = {
  registros: Artista[];
  contas: { id: string; name: string; email: string }[];
  estilos: { id: string; nome: string }[];
  criar: (entrada: EntradaArtista) => Promise<ResultadoGestao<unknown>>;
  editar: (entrada: EntradaEditarArtista) => Promise<ResultadoGestao<unknown>>;
  excluir: (id: string) => Promise<ResultadoGestao<unknown>>;
};
export function GestaoArtistas({ registros, contas, estilos, criar, editar, excluir }: Props) {
  const [editando, setEditando] = useState<Artista | null>(null);
  const [modo, setModo] = useState<"novo" | "existente">("novo");
  const gestao = useGestao();
  return (
    <div className="grid gap-8 lg:grid-cols-2">
      <section aria-labelledby="formulario-titulo" className="min-w-0">
        <h2 id="formulario-titulo" className="mb-4 font-display text-xl">
          {editando ? "Editar artista" : "Cadastrar artista"}
        </h2>
        {gestao.feedback}
        {!editando && (
          <div className="mb-4 grid gap-2">
            <label htmlFor="modo" className="text-nota font-semibold">
              Conta do artista
            </label>
            <select
              id="modo"
              value={modo}
              disabled={gestao.pendente}
              className={classeCampo}
              onChange={(evento) => {
                setModo(evento.target.value === "existente" ? "existente" : "novo");
                gestao.limpar();
              }}
            >
              <option value="novo">Criar nova conta</option>
              <option value="existente">Vincular conta existente</option>
            </select>
          </div>
        )}
        <FormularioAdmin
          key={editando?.id ?? modo}
          pendente={gestao.pendente}
          enviar={(dados, form) => {
            const perfil = {
              slug: texto(dados, "slug"),
              bio: texto(dados, "bio"),
              avatarUrl: texto(dados, "avatarUrl"),
              instagram: texto(dados, "instagram"),
              estilos: dados
                .getAll("estilos")
                .filter((valor): valor is string => typeof valor === "string"),
            };
            const pessoa = { nome: texto(dados, "nome"), telefone: texto(dados, "telefone") };
            const acao = editando
              ? () => editar({ ...perfil, ...pessoa, id: editando.id })
              : modo === "novo"
                ? () =>
                    criar({
                      ...perfil,
                      ...pessoa,
                      modo: "novo",
                      email: texto(dados, "email"),
                      senha: texto(dados, "senha"),
                    })
                : () => criar({ ...perfil, modo: "existente", userId: texto(dados, "userId") });
            void gestao.executar(
              acao,
              () => {
                form.reset();
                setEditando(null);
              },
              "Salvo com sucesso.",
            );
          }}
        >
          {!editando && modo === "existente" ? (
            <div className="grid gap-2">
              <label htmlFor="userId" className="text-nota font-semibold">
                Usuário existente
              </label>
              <select id="userId" name="userId" defaultValue="" required className={classeCampo}>
                <option value="">Selecione uma conta</option>
                {contas.map((conta) => (
                  <option key={conta.id} value={conta.id}>
                    {conta.name} — {conta.email}
                  </option>
                ))}
              </select>
              <p className="text-nota">
                A conta precisa estar ativa e sem perfil de artista. Contas CLIENTE passarão a
                ARTISTA.
              </p>
              {contas.length === 0 && (
                <p>Nenhuma conta disponível. Escolha criar uma nova conta.</p>
              )}
            </div>
          ) : (
            <>
              <CampoAdmin nome="nome" rotulo="Nome" valor={editando?.nome} obrigatorio />
              {editando ? (
                <p className="break-words text-nota">E-mail da conta: {editando.email}</p>
              ) : (
                <CampoAdmin nome="email" rotulo="E-mail" tipo="email" obrigatorio />
              )}
              <CampoAdmin
                nome="telefone"
                rotulo="Telefone"
                tipo="tel"
                valor={editando?.telefone}
                obrigatorio
              />
              {!editando && (
                <>
                  <CampoAdmin nome="senha" rotulo="Senha inicial" tipo="password" obrigatorio />
                  <p className="text-nota">
                    Use entre 8 e 128 caracteres. A senha pode ser alterada pelo artista em Minha
                    conta.
                  </p>
                </>
              )}
            </>
          )}
          <CampoAdmin nome="slug" rotulo="Slug" valor={editando?.slug} obrigatorio />
          <p className="text-nota">Use letras minúsculas, números e hífens, como ana-silva.</p>
          <CampoAdmin nome="bio" rotulo="Biografia" valor={editando?.bio} longo />
          <CampoAdmin
            nome="avatarUrl"
            rotulo="URL do avatar (HTTPS)"
            tipo="url"
            valor={editando?.avatarUrl}
          />
          <CampoAdmin nome="instagram" rotulo="Usuário do Instagram" valor={editando?.instagram} />
          <fieldset className="grid gap-2">
            <legend className="mb-2 text-nota font-semibold">Estilos do artista</legend>
            {estilos.length === 0 && (
              <p className="text-nota">Cadastre estilos para associá-los ao artista.</p>
            )}
            {estilos.map((estilo) => (
              <label key={estilo.id} className="flex items-center gap-2">
                <input
                  type="checkbox"
                  name="estilos"
                  value={estilo.id}
                  defaultChecked={editando?.estilos.includes(estilo.id)}
                  className="size-4 focus-visible:ring-3 focus-visible:ring-ring/50"
                />
                {estilo.nome}
              </label>
            ))}
          </fieldset>
          <Button type="submit">{gestao.pendente ? "Salvando…" : "Salvar artista"}</Button>
          {editando && (
            <Button
              type="button"
              variant="contorno"
              onClick={() => {
                setEditando(null);
                gestao.limpar();
              }}
            >
              Cancelar edição
            </Button>
          )}
        </FormularioAdmin>
      </section>
      <section aria-labelledby="lista-titulo" className="min-w-0">
        <h2 id="lista-titulo" className="mb-4 font-display text-xl">
          Artistas cadastrados
        </h2>
        {registros.length === 0 ? (
          <p>Nenhum artista cadastrado.</p>
        ) : (
          <ul className="grid gap-3">
            {registros.map((artista) => (
              <li
                key={artista.id}
                className="rounded-campo border-2 border-[var(--kolo-contorno)] p-4"
              >
                <p className="break-words font-semibold">{artista.nome}</p>
                <p className="break-words text-nota">
                  {artista.email} · {artista.slug}
                </p>
                <p className="text-nota">
                  Estilos:{" "}
                  {estilos
                    .filter((estilo) => artista.estilos.includes(estilo.id))
                    .map((estilo) => estilo.nome)
                    .join(", ") || "Nenhum"}
                </p>
                {artista.bio && <p className="break-words text-nota">{artista.bio}</p>}
                <div className="mt-3 flex flex-wrap gap-2">
                  <Button
                    type="button"
                    variant="contorno"
                    disabled={gestao.pendente}
                    aria-label={`Editar ${artista.nome}`}
                    onClick={() => {
                      setEditando(artista);
                      gestao.limpar();
                    }}
                  >
                    Editar
                  </Button>
                  <Button
                    type="button"
                    variant="contorno"
                    disabled={gestao.pendente}
                    aria-label={`Excluir ${artista.nome}`}
                    onClick={() => {
                      if (
                        window.confirm(
                          `Excluir o perfil de “${artista.nome}”? A conta será preservada; uma conta ARTISTA passará a CLIENTE e suas sessões serão encerradas.`,
                        )
                      )
                        void gestao.executar(
                          () => excluir(artista.id),
                          () => {
                            if (editando?.id === artista.id) setEditando(null);
                          },
                          "Perfil excluído. A conta foi preservada.",
                        );
                    }}
                  >
                    Excluir
                  </Button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import type { ResultadoGestao } from "@/modules/artists";
import type { EntradaEditarObra, EntradaObra } from "@/modules/catalog";
import {
  centavosParaTexto,
  formatarPreco,
  slugDoTitulo,
  type SituacaoObra,
} from "@/modules/catalog/cliente";
import { CampoAdmin, FormularioAdmin, classeCampo, texto, useGestao } from "./formulario";
import { GestaoImagensObra, type AcoesImagemObra } from "./gestao-imagens-obra";

export type ImagemObra = {
  id: string;
  chave: string;
  chaveMiniatura: string;
  ordem: number;
  principal: boolean;
  textoAlternativo: string;
};
export type ObraAdmin = {
  id: string;
  titulo: string;
  slug: string;
  descricao: string | null;
  artistaId: string;
  artistaNome: string;
  tecnica: string | null;
  dimensoes: string | null;
  ano: number | null;
  precoCentavos: number;
  estoque: number;
  situacao: SituacaoObra;
  destaque: boolean;
  tags: string[];
  imagens: ImagemObra[];
};
type Opcao = { id: string; nome: string };
type Props = {
  registros: ObraAdmin[];
  artistas: Opcao[];
  tags: Opcao[];
  criar: (entrada: EntradaObra) => Promise<ResultadoGestao<{ id: string }>>;
  editar: (entrada: EntradaEditarObra) => Promise<ResultadoGestao<unknown>>;
  excluir: (id: string) => Promise<ResultadoGestao<unknown>>;
  // Ações das imagens da obra em edição. Server Actions num objeto: uma função comum não
  // atravessa a fronteira servidor/cliente, por isso não é um render prop.
  acoesImagem?: AcoesImagemObra;
};

const ROTULO_SITUACAO: Record<SituacaoObra, string> = {
  RASCUNHO: "Rascunho",
  DISPONIVEL: "Disponível",
  ESGOTADA: "Esgotada",
};

export function GestaoObras({
  registros,
  artistas,
  tags,
  criar,
  editar,
  excluir,
  acoesImagem,
}: Props) {
  // O id, não o objeto: depois do refresh a obra em edição vem atualizada (imagens novas).
  const [editandoId, setEditandoId] = useState<string | null>(null);
  const editando = registros.find((obra) => obra.id === editandoId) ?? null;
  const gestao = useGestao();
  return (
    <div className="grid gap-8 lg:grid-cols-2">
      <section aria-labelledby="formulario-titulo" className="min-w-0">
        <h2 id="formulario-titulo" className="mb-4 font-display text-xl">
          {editando ? "Editar obra" : "Cadastrar obra"}
        </h2>
        {gestao.feedback}
        <FormularioAdmin
          key={editando?.id ?? "nova"}
          pendente={gestao.pendente}
          enviar={(dados, form) => {
            const ficha = {
              titulo: texto(dados, "titulo"),
              slug: texto(dados, "slug"),
              artistaId: texto(dados, "artistaId"),
              preco: texto(dados, "preco"),
              estoque: texto(dados, "estoque"),
              tecnica: texto(dados, "tecnica"),
              dimensoes: texto(dados, "dimensoes"),
              ano: texto(dados, "ano"),
              descricao: texto(dados, "descricao"),
              destaque: dados.get("destaque") === "on",
              tags: dados
                .getAll("tags")
                .filter((valor): valor is string => typeof valor === "string"),
            };
            if (editando) {
              const publicada = texto(dados, "situacao") === "publicada";
              void gestao.executar(
                () => editar({ ...ficha, id: editando.id, publicada }),
                () => undefined,
                "Obra salva.",
              );
              return;
            }
            let criada: string | null = null;
            void gestao.executar(
              async () => {
                const resultado = await criar(ficha);
                if (resultado.ok) criada = resultado.dados.id;
                return resultado;
              },
              () => {
                form.reset();
                // Abre a obra recém-criada para receber as imagens.
                setEditandoId(criada);
              },
              "Obra cadastrada como rascunho. Agora adicione as imagens.",
            );
          }}
        >
          <CampoAdmin nome="titulo" rotulo="Título" valor={editando?.titulo} obrigatorio />
          <CampoAdmin nome="slug" rotulo="Slug" valor={editando?.slug} obrigatorio />
          <div className="flex flex-wrap items-center gap-3">
            <Button
              type="button"
              variant="contorno"
              size="sm"
              onClick={(evento) => {
                const campos = evento.currentTarget.form?.elements;
                const titulo = campos?.namedItem("titulo");
                const slug = campos?.namedItem("slug");
                if (titulo instanceof HTMLInputElement && slug instanceof HTMLInputElement)
                  slug.value = slugDoTitulo(titulo.value);
              }}
            >
              Gerar slug pelo título
            </Button>
            <p className="text-nota">
              Letras minúsculas, números e hífens, como metropole-em-chamas.
            </p>
          </div>
          <div className="grid gap-2">
            <label htmlFor="artistaId" className="text-nota font-semibold">
              Artista
            </label>
            <select
              id="artistaId"
              name="artistaId"
              defaultValue={editando?.artistaId ?? ""}
              required
              className={classeCampo}
            >
              <option value="">Selecione o artista</option>
              {artistas.map((artista) => (
                <option key={artista.id} value={artista.id}>
                  {artista.nome}
                </option>
              ))}
            </select>
          </div>
          <div className="grid gap-2">
            <label htmlFor="preco" className="text-nota font-semibold">
              Preço (R$)
            </label>
            <input
              id="preco"
              name="preco"
              inputMode="decimal"
              placeholder="1.234,56"
              defaultValue={editando ? centavosParaTexto(editando.precoCentavos) : ""}
              required
              className={classeCampo}
            />
          </div>
          <CampoAdmin
            nome="estoque"
            rotulo="Estoque"
            tipo="number"
            valor={String(editando?.estoque ?? 1)}
            obrigatorio
          />
          <p className="text-nota">A maioria das obras é peça única: estoque 1.</p>
          <CampoAdmin nome="tecnica" rotulo="Técnica" valor={editando?.tecnica} />
          <CampoAdmin nome="dimensoes" rotulo="Dimensões" valor={editando?.dimensoes} />
          <CampoAdmin
            nome="ano"
            rotulo="Ano"
            tipo="number"
            valor={editando && editando.ano !== null ? String(editando.ano) : ""}
          />
          <CampoAdmin nome="descricao" rotulo="Descrição" valor={editando?.descricao} longo />
          <fieldset className="grid gap-2">
            <legend className="mb-2 text-nota font-semibold">Tags</legend>
            {tags.length === 0 && <p className="text-nota">Cadastre tags em Tags.</p>}
            {tags.map((tag) => (
              <label key={tag.id} className="flex items-center gap-2">
                <input
                  type="checkbox"
                  name="tags"
                  value={tag.id}
                  defaultChecked={editando?.tags.includes(tag.id)}
                  className="size-4 focus-visible:ring-3 focus-visible:ring-ring/50"
                />
                {tag.nome}
              </label>
            ))}
          </fieldset>
          <label className="flex items-center gap-2">
            <input
              type="checkbox"
              name="destaque"
              defaultChecked={editando?.destaque}
              className="size-4 focus-visible:ring-3 focus-visible:ring-ring/50"
            />
            Destacar na home
          </label>
          {editando && (
            <div className="grid gap-2">
              <label htmlFor="situacao" className="text-nota font-semibold">
                Situação
              </label>
              <select
                id="situacao"
                name="situacao"
                defaultValue={editando.situacao === "RASCUNHO" ? "rascunho" : "publicada"}
                className={classeCampo}
              >
                <option value="rascunho">Rascunho</option>
                <option value="publicada">Publicada</option>
              </select>
              <p className="text-nota">
                Publicar exige pelo menos uma imagem. Publicada fica disponível com estoque acima de
                0 e esgotada com estoque 0.
              </p>
            </div>
          )}
          <Button type="submit">{gestao.pendente ? "Salvando…" : "Salvar obra"}</Button>
          {editando && (
            <Button
              type="button"
              variant="contorno"
              onClick={() => {
                setEditandoId(null);
                gestao.limpar();
              }}
            >
              Cancelar edição
            </Button>
          )}
        </FormularioAdmin>
        {editando && acoesImagem && <GestaoImagensObra obra={editando} {...acoesImagem} />}
      </section>
      <section aria-labelledby="lista-titulo" className="min-w-0">
        <h2 id="lista-titulo" className="mb-4 font-display text-xl">
          Obras cadastradas
        </h2>
        {registros.length === 0 ? (
          <p>Nenhuma obra cadastrada.</p>
        ) : (
          <ul aria-labelledby="lista-titulo" className="grid gap-3">
            {registros.map((obra) => (
              <li
                key={obra.id}
                className="rounded-campo border-2 border-[var(--kolo-contorno)] p-4"
              >
                <p className="break-words font-semibold">{obra.titulo}</p>
                <p className="break-words text-nota">
                  {obra.artistaNome} · {ROTULO_SITUACAO[obra.situacao]}
                  {obra.destaque && " · Destaque"}
                </p>
                <p className="text-nota">
                  {formatarPreco(obra.precoCentavos)} · Estoque: {obra.estoque} ·{" "}
                  {obra.imagens.length === 1 ? "1 imagem" : `${obra.imagens.length} imagens`}
                </p>
                <div className="mt-3 flex flex-wrap gap-2">
                  <Button
                    type="button"
                    variant="contorno"
                    disabled={gestao.pendente}
                    aria-label={`Editar ${obra.titulo}`}
                    onClick={() => {
                      setEditandoId(obra.id);
                      gestao.limpar();
                    }}
                  >
                    Editar
                  </Button>
                  <Button
                    type="button"
                    variant="contorno"
                    disabled={gestao.pendente}
                    aria-label={`Excluir ${obra.titulo}`}
                    onClick={() => {
                      if (
                        window.confirm(
                          `Excluir a obra “${obra.titulo}”? Se ela estiver em carrinho ou pedido, será arquivada: sai da vitrine, mas o histórico fica preservado.`,
                        )
                      )
                        void gestao.executar(
                          () => excluir(obra.id),
                          () => {
                            if (editandoId === obra.id) setEditandoId(null);
                          },
                          "Obra excluída. Se estava em carrinho ou pedido, foi arquivada.",
                        );
                    }}
                  >
                    Excluir
                  </Button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import type { EntradaTaxonomia, ResultadoGestao, TipoTaxonomia } from "@/modules/artists";
import { CampoAdmin, FormularioAdmin, texto, useGestao } from "./formulario";

type Registro = { id: string; nome: string; slug: string; descricao: string | null };
export function GestaoTaxonomias({
  tipo,
  registros,
  salvar,
  excluir,
}: {
  tipo: TipoTaxonomia;
  registros: Registro[];
  salvar: (entrada: EntradaTaxonomia, id?: string) => Promise<ResultadoGestao<unknown>>;
  excluir: (id: string) => Promise<ResultadoGestao<unknown>>;
}) {
  const [editando, setEditando] = useState<Registro | null>(null);
  const gestao = useGestao();
  const singular = tipo === "estilos" ? "estilo" : "tag";
  return (
    <div className="grid gap-8 lg:grid-cols-2">
      <section aria-labelledby="formulario-titulo" className="min-w-0">
        <h2 id="formulario-titulo" className="mb-4 font-display text-xl">
          {editando ? "Editar" : "Cadastrar"} {singular}
        </h2>
        {gestao.feedback}
        <FormularioAdmin
          key={editando?.id ?? "novo"}
          pendente={gestao.pendente}
          enviar={(dados, form) => {
            void gestao.executar(
              () =>
                salvar(
                  {
                    nome: texto(dados, "nome"),
                    slug: texto(dados, "slug"),
                    descricao: texto(dados, "descricao"),
                  },
                  editando?.id,
                ),
              () => {
                form.reset();
                setEditando(null);
              },
              "Salvo com sucesso.",
            );
          }}
        >
          <CampoAdmin nome="nome" rotulo="Nome" valor={editando?.nome} obrigatorio />
          <CampoAdmin nome="slug" rotulo="Slug" valor={editando?.slug} obrigatorio />
          <p className="text-nota">Use letras minúsculas, números e hífens, como arte-urbana.</p>
          {tipo === "estilos" && (
            <CampoAdmin nome="descricao" rotulo="Descrição" valor={editando?.descricao} longo />
          )}
          <Button type="submit">{gestao.pendente ? "Salvando…" : `Salvar ${singular}`}</Button>
          {editando && (
            <Button
              type="button"
              variant="contorno"
              onClick={() => {
                setEditando(null);
                gestao.limpar();
              }}
            >
              Cancelar edição
            </Button>
          )}
        </FormularioAdmin>
      </section>
      <section aria-labelledby="lista-titulo" className="min-w-0">
        <h2 id="lista-titulo" className="mb-4 font-display text-xl">
          {tipo === "estilos" ? "Estilos cadastrados" : "Tags cadastradas"}
        </h2>
        {registros.length === 0 ? (
          <p>Nenhum {singular} cadastrado.</p>
        ) : (
          <ul className="grid gap-3">
            {registros.map((registro) => (
              <li
                key={registro.id}
                className="rounded-campo border-2 border-[var(--kolo-contorno)] p-4"
              >
                <p className="break-words font-semibold">{registro.nome}</p>
                <p className="break-words text-nota">{registro.slug}</p>
                {registro.descricao && (
                  <p className="break-words text-nota">{registro.descricao}</p>
                )}
                <div className="mt-3 flex flex-wrap gap-2">
                  <Button
                    type="button"
                    variant="contorno"
                    disabled={gestao.pendente}
                    aria-label={`Editar ${registro.nome}`}
                    onClick={() => {
                      setEditando(registro);
                      gestao.limpar();
                    }}
                  >
                    Editar
                  </Button>
                  <Button
                    type="button"
                    variant="contorno"
                    disabled={gestao.pendente}
                    aria-label={`Excluir ${registro.nome}`}
                    onClick={() => {
                      if (
                        window.confirm(
                          `Excluir ${singular} “${registro.nome}”? A ação só será permitida se não houver vínculos.`,
                        )
                      )
                        void gestao.executar(
                          () => excluir(registro.id),
                          () => {
                            if (editando?.id === registro.id) setEditando(null);
                          },
                          "Excluído com sucesso.",
                        );
                    }}
                  >
                    Excluir
                  </Button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

"use client";

import { useState } from "react";
import { unstable_rethrow, useRouter } from "next/navigation";
import { Button, buttonVariants } from "@/components/ui/button";
import { FormularioHorario } from "@/components/agenda/formulario-horario";
import type { AgendaDaSemana, HorarioAgenda } from "@/modules/scheduling";

type Resultado =
  { ok: true } | { ok: false; erro: string; mensagem: string; campos?: Record<string, string> };
type Props = AgendaDaSemana & {
  // Server Actions (src/app/agenda/actions.ts).
  cadastrar: (entrada: Record<string, string>) => Promise<Resultado>;
  editar: (entrada: Record<string, string>) => Promise<Resultado>;
  mudarSituacao: (entrada: {
    id: string;
    situacao: "CANCELADO" | "CONCLUIDO";
  }) => Promise<Resultado>;
};

const DIAS = ["Segunda", "Terça", "Quarta", "Quinta", "Sexta", "Sábado", "Domingo"];
const SITUACAO = { AGENDADO: "Agendado", CANCELADO: "Cancelado", CONCLUIDO: "Concluído" };

const diaMes = (data: string) => `${data.slice(8, 10)}/${data.slice(5, 7)}`;
const hora = (horario: string) => horario.slice(11, 16);

// A semana e o filtro de artista ficam na URL; "Esta semana" volta para a semana atual.
function hrefAgenda(semana: string | null, artista: string | null): string {
  const parametros = new URLSearchParams();
  if (semana) parametros.set("semana", semana);
  if (artista) parametros.set("artista", artista);
  const texto = parametros.toString();
  return texto ? `/agenda?${texto}` : "/agenda";
}

type Formulario = { modo: "novo" } | { modo: "editar"; horario: HorarioAgenda } | null;

// RF22/RN09/RN10: agenda da semana (segunda a domingo, horário de São Paulo). O artista vê e
// opera só a própria; o admin filtra por artista. Tudo chega pronto do servidor.
export function AgendaSemana({
  papel,
  artistaId,
  artistas,
  semana,
  dias,
  opcoes,
  cadastrar,
  editar,
  mudarSituacao,
}: Props) {
  const router = useRouter();
  const [formulario, setFormulario] = useState<Formulario>(null);
  const [mensagem, setMensagem] = useState<string | null>(null);
  const [pendente, setPendente] = useState(false);
  const admin = papel === "ADMIN";

  async function situacao(id: string, nova: "CANCELADO" | "CONCLUIDO") {
    setPendente(true);
    setMensagem(null);
    try {
      const resultado = await mudarSituacao({ id, situacao: nova });
      if (resultado.ok) router.refresh();
      else setMensagem(resultado.mensagem);
    } catch (falha) {
      unstable_rethrow(falha);
      setMensagem("Não foi possível atualizar agora. Tente novamente.");
    } finally {
      setPendente(false);
    }
  }

  function salvo() {
    setFormulario(null);
    router.refresh();
  }

  return (
    <>
      <div className="flex flex-wrap items-end justify-between gap-4">
        <div>
          <h1 className="font-display text-titulo-xl-mobile uppercase md:text-titulo-xl">Agenda</h1>
          <p className="text-nota">
            Semana de {diaMes(semana.inicio)} a {diaMes(semana.fim)}/{semana.fim.slice(0, 4)}
          </p>
        </div>
        {admin && (
          <div className="grid gap-1">
            <label htmlFor="agenda-artista" className="text-nota font-semibold">
              Artista
            </label>
            <select
              id="agenda-artista"
              defaultValue={artistaId ?? ""}
              onChange={(evento) =>
                router.push(hrefAgenda(semana.inicio, evento.target.value || null))
              }
              className="h-12 rounded-campo border-2 border-[var(--kolo-contorno)] bg-transparent px-3"
            >
              <option value="">Todos os artistas</option>
              {artistas.map((a) => (
                <option key={a.id} value={a.id}>
                  {a.nome}
                </option>
              ))}
            </select>
          </div>
        )}
      </div>

      <nav aria-label="Semanas" className="mt-6 flex flex-wrap gap-2">
        <a
          href={hrefAgenda(semana.anterior, artistaId && admin ? artistaId : null)}
          className={buttonVariants({ variant: "contorno", size: "sm" })}
        >
          Semana anterior
        </a>
        <a
          href={hrefAgenda(null, artistaId && admin ? artistaId : null)}
          className={buttonVariants({ variant: "contorno", size: "sm" })}
        >
          Esta semana
        </a>
        <a
          href={hrefAgenda(semana.proxima, artistaId && admin ? artistaId : null)}
          className={buttonVariants({ variant: "contorno", size: "sm" })}
        >
          Próxima semana
        </a>
      </nav>

      <div className="mt-6 grid gap-4">
        {formulario === null ? (
          <div>
            <Button type="button" onClick={() => setFormulario({ modo: "novo" })}>
              Novo horário
            </Button>
          </div>
        ) : (
          <FormularioHorario
            key={formulario.modo === "editar" ? formulario.horario.id : "novo"}
            artistas={admin ? artistas : []}
            opcoes={opcoes}
            inicial={formulario.modo === "editar" ? formulario.horario : undefined}
            enviar={formulario.modo === "editar" ? editar : cadastrar}
            aoSalvar={salvo}
            aoCancelar={() => setFormulario(null)}
          />
        )}
        {mensagem && (
          <p role="alert" className="text-destructive">
            {mensagem}
          </p>
        )}
      </div>

      <div className="mt-8 grid gap-6">
        {dias.map((dia, i) => {
          const titulo = `${DIAS[i]}, ${diaMes(dia.data)}`;
          const idTitulo = `dia-${dia.data}`;
          return (
            <section key={dia.data} aria-labelledby={idTitulo} className="grid gap-3">
              <h2 id={idTitulo} className="font-display text-titulo-lg uppercase">
                {titulo}
              </h2>
              {dia.horarios.length === 0 ? (
                <p className="text-nota">Sem horários</p>
              ) : (
                <ul className="grid gap-3">
                  {dia.horarios.map((h) => (
                    <li
                      key={h.id}
                      className="grid gap-2 rounded-card border-2 border-neutro-grafite bg-[var(--kolo-superficie)] p-4 text-[var(--kolo-superficie-texto)]"
                    >
                      <div className="flex flex-wrap items-center gap-3">
                        <span className="font-display text-titulo-lg">
                          {hora(h.inicio)}–{hora(h.fim)}
                        </span>
                        <span className="rounded-campo border-2 border-neutro-grafite px-2 py-0.5 font-display text-etiqueta uppercase">
                          {SITUACAO[h.situacao]}
                        </span>
                        {admin && <span className="font-semibold">{h.artistaNome}</span>}
                        <span className="text-nota">{h.codigo}</span>
                      </div>
                      <p>
                        <strong>{h.nomeContato}</strong> ·{" "}
                        <a
                          href={`tel:+55${h.telefoneContato}`}
                          className="text-[var(--kolo-link)] underline underline-offset-4"
                        >
                          {h.telefoneContato}
                        </a>
                        {h.emailCliente && ` · ${h.emailCliente}`}
                      </p>
                      {(h.estiloNome || h.tamanhoNome || h.regiaoCorpo) && (
                        <p className="text-nota">
                          {[h.estiloNome, h.tamanhoNome, h.regiaoCorpo].filter(Boolean).join(" · ")}
                        </p>
                      )}
                      {h.observacoes && <p className="whitespace-pre-line">{h.observacoes}</p>}
                      {h.situacao === "AGENDADO" && (
                        <div className="flex flex-wrap gap-2">
                          <Button
                            type="button"
                            variant="contorno"
                            size="sm"
                            aria-label={`Editar o horário de ${h.nomeContato}`}
                            onClick={() => setFormulario({ modo: "editar", horario: h })}
                          >
                            Editar
                          </Button>
                          <Button
                            type="button"
                            variant="contorno"
                            size="sm"
                            disabled={pendente}
                            aria-label={`Concluir o horário de ${h.nomeContato}`}
                            onClick={() => void situacao(h.id, "CONCLUIDO")}
                          >
                            Concluir
                          </Button>
                          <Button
                            type="button"
                            variant="contorno"
                            size="sm"
                            disabled={pendente}
                            aria-label={`Cancelar o horário de ${h.nomeContato}`}
                            onClick={() => void situacao(h.id, "CANCELADO")}
                          >
                            Cancelar
                          </Button>
                        </div>
                      )}
                    </li>
                  ))}
                </ul>
              )}
            </section>
          );
        })}
      </div>
    </>
  );
}

"use client";

import { useState } from "react";
import { unstable_rethrow } from "next/navigation";
import { useForm } from "react-hook-form";
import { AvisoErro, Campo } from "@/components/auth/campo";
import { resolverDe } from "@/components/auth/resolver";
import { Button } from "@/components/ui/button";
import {
  validarEndereco,
  type DadosEndereco,
  type EntradaEndereco,
  type ResultadoEndereco,
} from "@/modules/endereco";

const resolver = resolverDe(validarEndereco);

export function FormularioEndereco({
  dados,
  acao,
}: {
  dados: EntradaEndereco;
  acao: (entrada: EntradaEndereco) => Promise<ResultadoEndereco>;
}) {
  const [sucesso, setSucesso] = useState(false);
  const {
    register,
    handleSubmit,
    setError,
    reset,
    formState: { errors, isSubmitting },
  } = useForm<EntradaEndereco, unknown, DadosEndereco>({ resolver, defaultValues: dados });
  async function enviar(entrada: DadosEndereco) {
    try {
      const resultado = await acao({ ...entrada, complemento: entrada.complemento ?? "" });
      if (resultado.ok) {
        reset({ ...entrada, complemento: entrada.complemento ?? "" });
        setSucesso(true);
      } else if (resultado.erro === "invalido") {
        for (const [campo, mensagem] of Object.entries(resultado.campos))
          setError(campo as keyof EntradaEndereco, { message: mensagem });
      } else {
        setError("root.servidor", {
          message: "Sua sessão expirou. Entre novamente para continuar.",
        });
      }
    } catch (erro) {
      unstable_rethrow(erro);
      setError("root.servidor", { message: "Não foi possível salvar agora. Tente de novo." });
    }
  }
  return (
    <form
      noValidate
      onChange={() => setSucesso(false)}
      onSubmit={(evento) => {
        setSucesso(false);
        void handleSubmit(enviar)(evento);
      }}
      className="grid gap-5"
    >
      <Campo
        id="destinatario"
        rotulo="Nome de quem recebe"
        tipo="text"
        autoComplete="shipping name"
        registro={register("destinatario")}
        erro={errors.destinatario?.message}
      />
      <Campo
        id="cep"
        rotulo="CEP"
        tipo="text"
        autoComplete="shipping postal-code"
        registro={register("cep")}
        erro={errors.cep?.message}
      />
      <Campo
        id="logradouro"
        rotulo="Rua ou avenida"
        tipo="text"
        autoComplete="shipping address-line1"
        registro={register("logradouro")}
        erro={errors.logradouro?.message}
      />
      <Campo
        id="numero"
        rotulo="Número"
        tipo="text"
        autoComplete="off"
        registro={register("numero")}
        erro={errors.numero?.message}
      />
      <Campo
        id="complemento"
        rotulo="Complemento (opcional)"
        tipo="text"
        autoComplete="shipping address-line2"
        registro={register("complemento")}
        erro={errors.complemento?.message}
      />
      <Campo
        id="bairro"
        rotulo="Bairro"
        tipo="text"
        autoComplete="shipping address-level3"
        registro={register("bairro")}
        erro={errors.bairro?.message}
      />
      <Campo
        id="cidade"
        rotulo="Cidade"
        tipo="text"
        autoComplete="shipping address-level2"
        registro={register("cidade")}
        erro={errors.cidade?.message}
      />
      <Campo
        id="uf"
        rotulo="UF"
        tipo="text"
        autoComplete="shipping address-level1"
        registro={register("uf")}
        erro={errors.uf?.message}
      />
      <AvisoErro mensagem={errors.root?.servidor?.message} />
      {sucesso && (
        <p role="status" className="text-corpo">
          Endereço salvo com sucesso.
        </p>
      )}
      <Button type="submit" disabled={isSubmitting}>
        Salvar endereço
      </Button>
    </form>
  );
}

