// disputavam a banda do celular e o LCP do catálogo passava de 2,5 s no 4G simulado (PBI-45).

type Props = PaginaCatalogo & {
  // URL pública do R2 (R2_PUBLIC_URL); sem ela, as fotos viram espaço reservado.
  baseImagens: string | null;
};

const LINK_PAGINA =
  "grid h-12 min-w-12 place-items-center rounded-campo border-2 border-neutro-grafite px-3 font-display";

// RF09: grade pública de obras. Tudo chega pronto do servidor (listarCatalogo); a URL guarda a
// página e a ordenação, para o link poder ser compartilhado.
export function CatalogoObras({
  obras,
  total,
  pagina,
  totalPaginas,
  ordem,
  busca,
  baseImagens,
}: Props) {
  const inicio = (pagina - 1) * OBRAS_POR_PAGINA + 1;
  const fim = inicio + obras.length - 1;
  const catalogoVazio = total === 0 && !busca;
  return (
    <>
      <div className="flex flex-wrap items-end justify-between gap-4">
        <h1 className="font-display text-titulo-xl-mobile uppercase md:text-titulo-xl">
          Catálogo de obras
        </h1>
        {total > 0 && <SeletorOrdem ordem={ordem} busca={busca} />}
      </div>

      {/* PBI-41: busca por título, descrição ou técnica, sem acento; mantém a ordenação. */}
      {!catalogoVazio && (
        <form
          role="search"
          method="get"
          action="/obras"
          className="mt-6 flex max-w-xl flex-wrap items-end gap-2"
        >
          <label className="grid flex-1 gap-1">
            <span className="text-nota">Buscar obras</span>
            <input
              type="search"
              name="busca"
              defaultValue={busca}
              maxLength={100}
              placeholder="Título, técnica ou descrição"
              className="h-12 rounded-campo border-2 border-[var(--kolo-contorno)] bg-transparent px-3"
            />
          </label>
          {ordem !== "recentes" && <input type="hidden" name="ordem" value={ordem} />}
          <button type="submit" className={buttonVariants()}>
            Buscar
          </button>
        </form>
      )}

      {catalogoVazio ? (
        <p className="mt-8">Ainda não há obras publicadas.</p>
      ) : total === 0 ? (
        <div className="mt-8 grid max-w-md gap-4">
          <p>Nenhuma obra encontrada para “{busca}”.</p>
          <a href={hrefCatalogo(ordem)} className={buttonVariants({ variant: "contorno" })}>
            Limpar busca
          </a>
        </div>
      ) : obras.length === 0 ? (
        <div className="mt-8 grid max-w-md gap-4">
          <p>Esta página não tem obras.</p>
          <a
            href={hrefCatalogo(ordem, 1, busca)}
            className={buttonVariants({ variant: "contorno" })}
          >
            Ir para a primeira página
          </a>
        </div>
      ) : (
        <>
          <p className="mt-4 text-nota">
            Mostrando {inicio} a {fim} de {total} {total === 1 ? "obra" : "obras"}
            {busca && ` para “${busca}”`}
          </p>
          <div className="mt-6 grid gap-6 sm:grid-cols-2 lg:grid-cols-4">
            {obras.map((obra, i) => (
              <CardObra
                key={obra.slug}
                obra={obra}
                baseImagens={baseImagens}
                prioridade={i === 0}
              />
            ))}
          </div>
          {totalPaginas > 1 && (
            <nav aria-label="Paginação" className="mt-10">
              <ul className="flex flex-wrap items-center justify-center gap-2">
                {pagina > 1 && (
                  <li>
                    <a href={hrefCatalogo(ordem, pagina - 1, busca)} className={LINK_PAGINA}>
                      Anterior
                    </a>
                  </li>
                )}
                {Array.from({ length: totalPaginas }, (_, i) => i + 1).map((numero) => (
                  <li key={numero}>
                    {numero === pagina ? (
                      <span
                        aria-current="page"
                        className={`${LINK_PAGINA} bg-primary text-primary-foreground`}
                      >
                        {numero}
                      </span>
                    ) : (
                      <a href={hrefCatalogo(ordem, numero, busca)} className={LINK_PAGINA}>
                        {numero}
                      </a>
                    )}
                  </li>
                ))}
                {pagina < totalPaginas && (
                  <li>
                    <a href={hrefCatalogo(ordem, pagina + 1, busca)} className={LINK_PAGINA}>
                      Próxima
                    </a>
                  </li>
                )}
              </ul>
            </nav>
          )}
        </>
      )}
    </>
  );
}

"use client";

import { useEffect, useState } from "react";
import { unstable_rethrow } from "next/navigation";
import { Button, buttonVariants } from "@/components/ui/button";
import { formatarPreco } from "@/modules/catalog/cliente";
import type { PedidoResumo, SituacaoPedido } from "@/modules/orders";
import { ROTULO_MODALIDADE } from "@/modules/orders/cliente";
import { prazoParaPagar } from "@/modules/payments/cliente";

const SITUACAO: Record<SituacaoPedido, string> = {
  PENDENTE: "Aguardando pagamento",
  PAGO: "Pago",
  PROCESSANDO: "Em preparação",
  ENVIADO: "Enviado",
  ENTREGUE: "Entregue",
  CANCELADO: "Pedido cancelado",
};

type Recusa = { ok: false; erro: string; mensagem: string };
type Props = {
  pedido: PedidoResumo;
  // Server Action: em sucesso redireciona para o Checkout Pro; só volta quando recusa.
  pagar: (numero: string) => Promise<Recusa>;
  // Chegou pelas back_urls do Checkout Pro. Só muda o aviso: quem confirma é o webhook (RN05).
  voltouDoPagamento?: boolean;
  // Instante do render no servidor (ms): o primeiro render usa o mesmo relógio nos dois lados,
  // para a hidratação não divergir quando o prazo vence entre um e outro.
  agora?: number;
};

function restanteDe(expiraEm: Date | null, agora: number = Date.now()): number {
  return expiraEm ? Math.max(0, expiraEm.getTime() - agora) : 0;
}

function mmss(ms: number): string {
  const segundos = Math.ceil(ms / 1000);
  const minutos = Math.floor(segundos / 60);
  return `${String(minutos).padStart(2, "0")}:${String(segundos % 60).padStart(2, "0")}`;
}

// RN03: as unidades ficam presas por 10 minutos, e o checkout fecha 2 minutos antes (RN06, folga
// para o webhook). O cronômetro só informa; quem decide o prazo é o servidor.
export function PedidoCheckout({ pedido, pagar, voltouDoPagamento = false, agora }: Props) {
  const [restante, setRestante] = useState(() =>
    restanteDe(prazoParaPagar(pedido.reservaExpiraEm), agora),
  );
  const [abrindo, setAbrindo] = useState(false);
  const [recusa, setRecusa] = useState<Recusa | null>(null);
  const pendente = pedido.situacao === "PENDENTE";

  async function abrirPagamento() {
    setAbrindo(true);
    setRecusa(null);
    try {
      setRecusa(await pagar(pedido.numero));
    } catch (falha) {
      // O redirect para o Mercado Pago chega como erro interno do Next e precisa seguir adiante.
      // O botão fica travado até a página sair: um segundo clique abriria outra preferência.
      unstable_rethrow(falha);
      setRecusa({
        ok: false,
        erro: "falha",
        mensagem: "Não foi possível abrir o pagamento agora. Tente de novo em instantes.",
      });
    }
    setAbrindo(false);
  }

  // Voltar do Mercado Pago pelo histórico pode restaurar a página do cache (bfcache) com o botão
  // ainda travado pelo redirect: o cliente precisa poder tentar de novo.
  useEffect(() => {
    const aoVoltar = (evento: PageTransitionEvent) => {
      if (evento.persisted) setAbrindo(false);
    };
    window.addEventListener("pageshow", aoVoltar);
    return () => window.removeEventListener("pageshow", aoVoltar);
  }, []);

  useEffect(() => {
    if (!pendente || !pedido.reservaExpiraEm) return;
    const fim = prazoParaPagar(pedido.reservaExpiraEm);
    // Montado, o relógio passa a ser o do navegador.
    setRestante(restanteDe(fim));
    const relogio = setInterval(() => setRestante(restanteDe(fim)), 1000);
    return () => clearInterval(relogio);
  }, [pendente, pedido.reservaExpiraEm]);

  const { endereco } = pedido;
  return (
    <>
      <p className="font-display text-selo uppercase">{SITUACAO[pedido.situacao]}</p>
      <h1 className="mt-2 break-words font-display text-titulo-xl-mobile uppercase md:text-titulo-xl">
        Pedido {pedido.numero}
      </h1>
      <div className="mt-8 grid gap-8 lg:grid-cols-[minmax(0,1fr)_24rem]">
        <div className="grid content-start gap-6">
          {pendente && voltouDoPagamento && (
            <div
              role="status"
              className="grid gap-2 rounded-card border-2 border-neutro-grafite p-5"
            >
              <p className="font-display uppercase">Estamos confirmando seu pagamento</p>
              <p>
                Assim que o Mercado Pago aprovar, o pedido passa para Pago. Com Pix ou boleto, a
                confirmação chega depois que o pagamento é compensado.
              </p>
            </div>
          )}
          {pendente && restante > 0 && (
            <div
              role="timer"
              aria-live="off"
              className="rounded-card border-2 border-neutro-grafite bg-primary p-5 text-primary-foreground shadow-adesivo-sm"
            >
              <p className="font-display uppercase">
                Você tem{" "}
                <span suppressHydrationWarning className="text-titulo-lg">
                  {mmss(restante)}
                </span>{" "}
                para iniciar o pagamento
              </p>
              <p className="mt-2">
                Suas obras ficam reservadas até lá; depois disso, voltam à vitrine.
              </p>
            </div>
          )}
          {pendente && restante === 0 && (
            <div role="status" className="grid gap-3 rounded-card border-2 border-destructive p-5">
              <p className="font-display uppercase text-destructive">O prazo para pagar acabou</p>
              <p>As obras voltam a ficar disponíveis. Finalize de novo pelo carrinho.</p>
              <div>
                <a href="/carrinho" className={buttonVariants({ variant: "contorno", size: "sm" })}>
                  Voltar ao carrinho
                </a>
              </div>
            </div>
          )}
          <section aria-labelledby="pedido-endereco" className="grid gap-2">
            <h2 id="pedido-endereco" className="font-display text-titulo-lg uppercase">
              Endereço do pedido
            </h2>
            <address className="grid gap-1 not-italic">
              <strong>{endereco.destinatario}</strong>
              <span>
                {endereco.logradouro}, {endereco.numero}
                {endereco.complemento && ` — ${endereco.complemento}`}
              </span>
              <span>
                {endereco.bairro}, {endereco.cidade} / {endereco.uf} · CEP {endereco.cep}
              </span>
            </address>
          </section>
        </div>

        <aside
          aria-labelledby="pedido-resumo"
          className="grid content-start gap-4 rounded-card border-2 border-neutro-grafite p-5"
        >
          <h2 id="pedido-resumo" className="font-display text-titulo-lg uppercase">
            Resumo do pedido
          </h2>
          <ul className="grid gap-2">
            {pedido.itens.map((item) => (
              <li key={item.obraId} className="flex justify-between gap-4">
                <span className="min-w-0 break-words">{item.titulo}</span>
                <span className="shrink-0">
                  {formatarPreco(item.precoCentavos)}
                  {item.quantidade > 1 && ` × ${item.quantidade}`}
                </span>
              </li>
            ))}
          </ul>
          <dl className="grid gap-2 border-t-2 border-neutro-grafite pt-3">
            <div className="flex justify-between gap-4">
              <dt>Subtotal</dt>
              <dd>{formatarPreco(pedido.subtotalCentavos)}</dd>
            </div>
            <div className="flex justify-between gap-4">
              <dt>{ROTULO_MODALIDADE[pedido.modalidade]}</dt>
              <dd>{formatarPreco(pedido.freteCentavos)}</dd>
            </div>
            <div className="flex justify-between gap-4 border-t-2 border-neutro-grafite pt-2 font-display text-titulo-lg">
              <dt>Total</dt>
              <dd>{formatarPreco(pedido.totalCentavos)}</dd>
            </div>
          </dl>
          {pendente && restante > 0 && (
            <>
              {recusa && (
                <p role="alert" className="text-destructive">
                  {recusa.mensagem}
                </p>
              )}
              <Button
                type="button"
                size="lg"
                disabled={abrindo}
                onClick={() => void abrirPagamento()}
              >
                {abrindo ? "Abrindo o pagamento…" : "Pagar com Mercado Pago"}
              </Button>
              <p className="text-nota">
                Você paga com Pix, cartão ou boleto no ambiente seguro do Mercado Pago.
              </p>
            </>
          )}
        </aside>
      </div>
    </>
  );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { UploadImagem } from "@/components/media/upload-imagem";
import { CampoAdmin, FormularioAdmin, texto, useGestao } from "@/components/admin/formulario";
import type { EntradaUpload, ResultadoUpload, ResultadoProcessamento } from "@/modules/media";
import type { ResultadoPortfolio, TrabalhoPortfolio } from "@/modules/portfolio";

export type AcoesFormulario = {
  criar: (entrada: unknown) => Promise<ResultadoPortfolio<unknown>>;
  editar: (entrada: unknown) => Promise<ResultadoPortfolio<unknown>>;
  solicitar: (entrada: EntradaUpload) => Promise<ResultadoUpload>;
  processar: (chave: string) => Promise<ResultadoProcessamento>;
};

type Props = AcoesFormulario & {
  artistaId: string;
  estilos: { id: string; nome: string }[];
  trabalho?: TrabalhoPortfolio;
  aoCancelar: () => void;
};

export function FormularioTrabalho({
  artistaId,
  estilos,
  trabalho,
  criar,
  editar,
  solicitar,
  processar,
  aoCancelar,
}: Props) {
  const gestao = useGestao();
  const [enviando, setEnviando] = useState(false);
  const [imagemPendente, setImagemPendente] = useState(false);
  const [chave, setChave] = useState<string>();
  const [erroImagem, setErroImagem] = useState(false);
  const [versaoUpload, setVersaoUpload] = useState(0);
  return (
    <section
      aria-labelledby="formulario-trabalho-titulo"
      className="min-w-0 [&_fieldset]:min-w-0 [&_fieldset]:grid-cols-1 [&_input]:max-w-full"
    >
      <h2 id="formulario-trabalho-titulo" className="mb-4 font-display text-xl">
        {trabalho ? "Editar trabalho" : "Cadastrar trabalho"}
      </h2>
      {gestao.feedback}
      <FormularioAdmin
        pendente={gestao.pendente}
        enviar={(dados, form) => {
          if (enviando || imagemPendente) return;
          if (!trabalho && !chave) {
            setErroImagem(true);
            return;
          }
          const ficha = {
            artistaId,
            titulo: texto(dados, "titulo"),
            descricao: texto(dados, "descricao"),
            regiaoCorpo: texto(dados, "regiaoCorpo"),
            destaque: dados.get("destaque") === "on",
            estilos: dados.getAll("estilos").filter((v): v is string => typeof v === "string"),
            ...(chave ? { chave } : {}),
          };
          void gestao.executar(
            () => (trabalho ? editar({ ...ficha, id: trabalho.id }) : criar(ficha)),
            () => {
              setChave(undefined);
              setVersaoUpload((v) => v + 1);
              if (!trabalho) form.reset();
            },
            trabalho ? "Trabalho salvo." : "Trabalho cadastrado.",
          );
        }}
      >
        <CampoAdmin nome="titulo" rotulo="Título" valor={trabalho?.titulo} obrigatorio />
        <CampoAdmin nome="descricao" rotulo="Descrição" valor={trabalho?.descricao} longo />
        <p className="text-nota">
          Descreva a tatuagem no título e na descrição para ajudar quem usa leitor de tela.
        </p>
        <CampoAdmin nome="regiaoCorpo" rotulo="Região do corpo" valor={trabalho?.regiaoCorpo} />
        <fieldset className="grid gap-2">
          <legend className="mb-2 font-semibold">Estilos</legend>
          {estilos.length === 0 && <p>Nenhum estilo cadastrado.</p>}
          {estilos.map((e) => (
            <label key={e.id} className="flex items-center gap-2">
              <input
                type="checkbox"
                name="estilos"
                value={e.id}
                defaultChecked={trabalho?.estilos.includes(e.id)}
              />
              {e.nome}
            </label>
          ))}
        </fieldset>
        <label className="flex items-center gap-2">
          <input type="checkbox" name="destaque" defaultChecked={trabalho?.destaque} />
          Destacar trabalho
        </label>
        {trabalho && (
          <p className="text-nota">Envie outra imagem somente se quiser substituir a atual.</p>
        )}
        <UploadImagem
          key={versaoUpload}
          destino="portfolio"
          aoEnviar={(pendente) => {
            setEnviando(pendente);
            if (pendente) {
              setChave(undefined);
              setImagemPendente(true);
            }
          }}
          artistId={artistaId}
          solicitar={solicitar}
          processar={processar}
          aoConcluir={(imagem) => {
            setChave(imagem.chave);
            setImagemPendente(false);
            setErroImagem(false);
          }}
        />
        {erroImagem && <p role="alert">Envie uma imagem antes de salvar o trabalho.</p>}
        {trabalho && imagemPendente && !enviando && (
          <Button
            type="button"
            variant="contorno"
            onClick={() => {
              setImagemPendente(false);
              setChave(undefined);
              setErroImagem(false);
              setVersaoUpload((v) => v + 1);
            }}
          >
            Manter imagem atual
          </Button>
        )}
        <Button type="submit" disabled={enviando || imagemPendente}>
          {gestao.pendente ? "Salvando…" : "Salvar trabalho"}
        </Button>
        {trabalho && (
          <Button type="button" variant="contorno" onClick={aoCancelar}>
            Cancelar edição
          </Button>
        )}
      </FormularioAdmin>
    </section>
  );
}

import Image from "next/image";
import { buttonVariants } from "@/components/ui/button";
import type { GaleriaPublica } from "@/modules/portfolio";

export function GaleriaTatuagens({
  trabalhos,
  artistas,
  estilos,
  regioes,
  filtros,
  baseImagens,
}: GaleriaPublica & { baseImagens: string | null }) {
  const base = baseImagens?.replace(/\/+$/, "");
  // RF18 (PBI-37): com busca ou filtro ativo, mostra a contagem e o caminho para limpar tudo.
  const filtrado = Boolean(filtros.artista || filtros.estilo || filtros.regiao);
  const ativo = filtrado || Boolean(filtros.busca);
  const vazio = filtros.busca
    ? `Nenhum trabalho encontrado para “${filtros.busca}”${filtrado ? " com os filtros selecionados" : ""}.`
    : "Nenhum trabalho encontrado para os filtros selecionados.";
  return (
    <>
      <h1 className="font-display text-titulo-xl-mobile uppercase md:text-titulo-xl">
        Galeria de tatuagens
      </h1>
      <form action="/tatuagens" method="get" className="mt-6 flex flex-wrap items-end gap-3">
        <label className="grid w-full gap-1 sm:w-72">
          <span className="text-nota">Buscar por palavra-chave</span>
          <input
            type="search"
            name="busca"
            defaultValue={filtros.busca}
            maxLength={100}
            placeholder="Estilo, elemento ou tatuador"
            className="h-12 max-w-full rounded-campo border-2 border-[var(--kolo-contorno)] bg-background px-3"
          />
        </label>
        {[
          { nome: "artista", rotulo: "Artista", valor: filtros.artista, opcoes: artistas },
          { nome: "estilo", rotulo: "Estilo", valor: filtros.estilo, opcoes: estilos },
          {
            nome: "regiao",
            rotulo: "Região do corpo",
            valor: filtros.regiao,
            opcoes: regioes.map((r) => ({ id: r, nome: r })),
          },
        ].map((campo) => (
          <label key={campo.nome} className="grid w-full gap-1 sm:w-auto">
            <span className="text-nota">{campo.rotulo}</span>
            <select
              name={campo.nome}
              defaultValue={campo.valor ?? ""}
              className="h-12 max-w-full rounded-campo border-2 border-[var(--kolo-contorno)] bg-background px-3"
            >
              <option value="">Todos</option>
              {campo.valor && !campo.opcoes.some((o) => o.id === campo.valor) && (
                <option value={campo.valor}>Seleção indisponível</option>
              )}
              {campo.opcoes.map((o) => (
                <option key={o.id} value={o.id}>
                  {o.nome}
                </option>
              ))}
            </select>
          </label>
        ))}
        <button type="submit" className={buttonVariants()}>
          Filtrar
        </button>
        {ativo && (
          <a href="/tatuagens" className={buttonVariants({ variant: "contorno" })}>
            Limpar busca e filtros
          </a>
        )}
      </form>
      {trabalhos.length === 0 ? (
        <p className="mt-8" role="status">
          {ativo ? vazio : "Ainda não há tatuagens cadastradas."}
        </p>
      ) : (
        ativo && (
          <p className="mt-6 text-nota" role="status">
            {trabalhos.length === 1
              ? "1 trabalho encontrado"
              : `${trabalhos.length} trabalhos encontrados`}
          </p>
        )
      )}
      <div className="mt-8 grid gap-6 sm:grid-cols-2 lg:grid-cols-4">
        {trabalhos.map((t, i) => (
          <article
            key={t.id}
            className="overflow-hidden rounded-card border-2 border-neutro-grafite bg-[var(--kolo-superficie)] text-[var(--kolo-superficie-texto)] shadow-adesivo-sm"
          >
            <div className="relative aspect-[4/3] border-b-2 border-neutro-grafite">
              {base ? (
                <Image
                  src={`${base}/${t.imagem}`}
                  alt={t.textoAlternativo}
                  fill
                  sizes="(min-width: 1024px) 22vw, (min-width: 640px) 45vw, 100vw"
                  loading={i < 4 ? "eager" : "lazy"}
                  className="object-cover"
                />
              ) : (
                <div className="grid h-full place-items-center">Imagem indisponível</div>
              )}
            </div>
            <div className="grid gap-1 p-4">
              <p className="font-display text-etiqueta uppercase text-[var(--kolo-link)]">
                {t.artistaNome}
              </p>
              <h2 className="break-words font-display text-titulo-lg uppercase">{t.titulo}</h2>
              <p className="text-nota">
                {[...t.estilos, t.regiaoCorpo].filter(Boolean).join(" · ")}
              </p>
            </div>
          </article>
        ))}
      </div>
    </>
  );
}

