  EntradaWizard,
  OpcoesWizard,
  PreferenciaWizard,
  ResultadoWizard,
} from "@/modules/scheduling";

// A etapa 8 (WhatsApp, PBI-33) é a revisão: o formulário vai até os Avisos.
const ETAPAS = [
  "Nome",
  "Artista",
  "Estilo",
  "Região",
  "Tamanho",
  "Preferência",
  "Avisos",
  "WhatsApp",
];
const ULTIMA = ETAPAS.length - 2;
const FINAL = ETAPAS.length - 1;
// RF23–RF25: avisos sobre o que acontece no estúdio; o aceite não é gravado (RNF18).
const AVISOS = [
  {
    chave: "anamnese",
    Icone: TriangleAlert,
    texto:
      "A ficha de anamnese será preenchida presencialmente. Se não comparecer para preenchê-la, o horário pode ser cancelado.",
  },
  {
    chave: "termo",
    Icone: CircleAlert,
    texto:
      "O termo de consentimento será assinado presencialmente. Sem a assinatura, o horário pode ser cancelado.",
  },
  {
    chave: "maioridade",
    Icone: ShieldCheck,
    texto:
      "Declaro ter 18 anos ou mais. Meu documento com foto será conferido no estúdio; sem ele, o horário será cancelado.",
  },
] as const;
// O foco vai para o título a cada etapa; a margem de rolagem (maior que o cabeçalho fixo, ~82 px)
// impede que o título focado fique escondido embaixo dele no celular.
const TITULO = "scroll-mt-28 font-display text-2xl";
const CAMPO =
  "mt-2 min-h-12 w-full rounded-campo border-2 border-[var(--kolo-contorno)] bg-[var(--kolo-superficie)] px-3 py-2 text-[var(--kolo-superficie-texto)] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--kolo-acao)]";
const INICIAL: EntradaWizard = {
  nome: "",
  artistaId: "",
  estiloId: "",
  regiao: "",
  tamanhoId: "",
  data: "",
  horario: "",
  aceites: { anamnese: false, termo: false, maioridade: false },
};

export function WizardAgendamento({
  opcoes,
  revisar,
}: {
  opcoes: OpcoesWizard;
  revisar: (entrada: EntradaWizard) => Promise<ResultadoWizard<PreferenciaWizard>>;
}) {
  const [etapa, setEtapa] = useState(0);
  const [dados, setDados] = useState<EntradaWizard>(INICIAL);
  const [resumo, setResumo] = useState<PreferenciaWizard | null>(null);
  const [erro, setErro] = useState("");
  const [ocupado, setOcupado] = useState(false);
  const titulo = useRef<HTMLHeadingElement>(null);
  const artista = opcoes.artistas.find(({ id }) => id === dados.artistaId);
  const vazio = opcoes.artistas.length === 0 || opcoes.tamanhos.length === 0;
  const hoje = new Date().toLocaleDateString("sv-SE", { timeZone: "America/Sao_Paulo" });

  useEffect(() => {
    titulo.current?.focus();
  }, [etapa, resumo]);

  function alterar(campo: Exclude<keyof EntradaWizard, "aceites">, valor: string) {
    setDados((atual) => ({
      ...atual,
      [campo]: valor,
      ...(campo === "artistaId" && valor !== atual.artistaId ? { estiloId: "" } : {}),
    }));
    setErro("");
    setResumo(null);
  }

  function marcarAviso(chave: keyof EntradaWizard["aceites"], marcado: boolean) {
    setDados((atual) => ({ ...atual, aceites: { ...atual.aceites, [chave]: marcado } }));
    setErro("");
    setResumo(null);
  }

  async function avancar(evento: FormEvent<HTMLFormElement>) {
    evento.preventDefault();
    if (ocupado) return;
    const formulario = evento.currentTarget;
    const campos = Array.from(
      formulario.querySelectorAll<HTMLInputElement | HTMLSelectElement>("input, select"),
    );
    const invalido = campos.find(
      (campo) =>
        !campo.checkValidity() ||
        ((campo.name === "nome" || campo.name === "regiao") && campo.value.trim().length < 2),
    );
    if (invalido) {
      setErro(
        invalido.type === "checkbox"
          ? "Confirme os três avisos para continuar."
          : "Preencha corretamente os campos desta etapa para continuar.",
      );
      invalido.focus();
      return;
    }
    if (etapa < ULTIMA) {
      setErro("");
      setEtapa(etapa + 1);
      return;
    }
    setOcupado(true);
    setErro("");
    try {
      const resultado = await revisar(dados);
      if (resultado.ok) setResumo(resultado.dados);
      else setErro(resultado.mensagem);
    } catch (falha) {
      unstable_rethrow(falha);
      setErro("Não foi possível revisar suas preferências. Tente novamente.");
    } finally {
      setOcupado(false);
    }
  }

  function voltar() {
    setErro("");
    setEtapa((atual) => Math.max(0, atual - 1));
  }

  if (vazio)
    return (
      <p role="status">
        Ainda não há opções disponíveis para agendamento. Tente novamente mais tarde.
      </p>
    );

  const erroId = erro ? "wizard-erro" : undefined;
  return (
    <div className="min-w-0">
      <ol
        aria-label="Etapas do agendamento"
        className="mb-8 grid grid-cols-2 gap-2 text-sm sm:grid-cols-4 lg:grid-cols-8"
      >
        {ETAPAS.map((nome, indice) => {
          const atual = resumo ? indice === FINAL : etapa === indice;
          return (
            <li
              key={nome}
              aria-current={atual ? "step" : undefined}
              className={`rounded-campo border p-2 ${atual ? "border-[var(--kolo-acao)] font-bold" : "border-[var(--kolo-contorno)]"}`}
            >
              {indice + 1}. {nome}
            </li>
          );
        })}
      </ol>
      {resumo ? (
        <section aria-labelledby="wizard-titulo">
          <h2 id="wizard-titulo" ref={titulo} tabIndex={-1} className={TITULO}>
            Revise suas preferências
          </h2>
          <dl className="my-6 grid gap-3 break-words">
            {[
              ["Nome", resumo.nome],
              ["Artista", artista?.nome],
              ["Estilo", artista?.estilos.find(({ id }) => id === resumo.estiloId)?.nome],
              ["Região", resumo.regiao],
              ["Tamanho", opcoes.tamanhos.find(({ id }) => id === resumo.tamanhoId)?.nome],
              [
                "Preferência",
                `${resumo.data.split("-").reverse().join("/")} às ${resumo.horario} (São Paulo)`,
              ],
            ].map(([rotulo, valor]) => (
              <div key={rotulo}>
                <dt className="font-bold">{rotulo}</dt>
                <dd>{valor}</dd>
              </div>
            ))}
          </dl>
          {/* RF21 (PBI-33): a mensagem montada no servidor; quem envia é a própria pessoa. */}
          <section aria-labelledby="wizard-previa" className="mb-6 grid gap-3">
            <h3 id="wizard-previa" className="font-display text-xl">
              Prévia da sua mensagem
            </h3>
            <p className="whitespace-pre-line break-words rounded-card bg-[var(--kolo-superficie)] p-4 text-[var(--kolo-superficie-texto)]">
              {resumo.mensagem}
            </p>
          </section>
          <p className="mb-6">
            As fotos de referência você manda direto na conversa. O site não guarda o pedido nem
            reserva horário: o atendimento começa quando você enviar a mensagem.
          </p>
          <div className="flex flex-wrap gap-3">
            <a
              href={resumo.linkWhatsApp}
              target="_blank"
              rel="noopener noreferrer"
              className={buttonVariants({
                className: "h-auto min-h-12 max-w-full whitespace-normal py-3",
              })}
            >
              <MessageCircle aria-hidden />
              Abrir conversa no WhatsApp
            </a>
            <Button
              type="button"
              variant="contorno"
              onClick={() => {
                setResumo(null);
                setErro("");
              }}
            >
              Editar preferências
            </Button>
          </div>
        </section>
      ) : (
        <form noValidate onSubmit={avancar} aria-busy={ocupado} className="grid gap-5">
          <h2 id="wizard-titulo" ref={titulo} tabIndex={-1} className={TITULO}>
            {etapa + 1}. {ETAPAS[etapa]}
          </h2>
          {etapa === 0 && (
            <label htmlFor="wizard-nome">
              Seu nome
              <input
                id="wizard-nome"
                name="nome"
                disabled={ocupado}
                autoComplete="name"
                required
                minLength={2}
                maxLength={100}
                className={CAMPO}
                value={dados.nome}
                onChange={(e) => alterar("nome", e.target.value)}
                aria-describedby={erroId}
                aria-invalid={!!erro}
              />
            </label>
          )}
          {etapa === 1 && (
            <label htmlFor="wizard-artista">
              Artista
              <select
                id="wizard-artista"
                name="artistaId"
                disabled={ocupado}
                required
                className={CAMPO}
                value={dados.artistaId}
                onChange={(e) => alterar("artistaId", e.target.value)}
                aria-describedby={erroId}
                aria-invalid={!!erro}
              >
                <option value="">Selecione um artista</option>
                {opcoes.artistas.map(({ id, nome }) => (
                  <option key={id} value={id}>
                    {nome}
                  </option>
                ))}
              </select>
            </label>
          )}
          {etapa === 2 && (
            <div>
              <label htmlFor="wizard-estilo">
                Estilo
                <select
                  id="wizard-estilo"
                  name="estiloId"
                  disabled={ocupado}
                  required
                  className={CAMPO}
                  value={dados.estiloId}
                  onChange={(e) => alterar("estiloId", e.target.value)}
                  aria-describedby={erroId}
                  aria-invalid={!!erro}
                >
                  <option value="">Selecione um estilo</option>
                  {artista?.estilos.map(({ id, nome }) => (
                    <option key={id} value={id}>
                      {nome}
                    </option>
                  ))}
                </select>
              </label>
              {artista?.estilos.length === 0 && (
                <p role="status" className="mt-3">
                  Este artista ainda não tem estilos disponíveis. Volte e escolha outro artista.
                </p>
              )}
            </div>
          )}
          {etapa === 3 && (
            <label htmlFor="wizard-regiao">
              Região do corpo
              <input
                id="wizard-regiao"
                name="regiao"
                disabled={ocupado}
                required
                minLength={2}
                maxLength={80}
                placeholder="Ex.: antebraço"
                className={CAMPO}
                value={dados.regiao}
                onChange={(e) => alterar("regiao", e.target.value)}
                aria-describedby={erroId}
                aria-invalid={!!erro}
              />
            </label>
          )}
          {etapa === 4 && (
            <label htmlFor="wizard-tamanho">
              Tamanho aproximado
              <select
                id="wizard-tamanho"
                name="tamanhoId"
                disabled={ocupado}
                required
                className={CAMPO}
                value={dados.tamanhoId}
                onChange={(e) => alterar("tamanhoId", e.target.value)}
                aria-describedby={erroId}
                aria-invalid={!!erro}
              >
                <option value="">Selecione um tamanho</option>
                {opcoes.tamanhos.map(({ id, nome }) => (
                  <option key={id} value={id}>
                    {nome}
                  </option>
                ))}
              </select>
            </label>
          )}
          {etapa === 5 && (
            <div className="grid gap-5 sm:grid-cols-2">
              <label htmlFor="wizard-data">
                Data de preferência
                <input
                  id="wizard-data"
                  name="data"
                  disabled={ocupado}
                  type="date"
                  required
                  min={hoje}
                  className={CAMPO}
                  value={dados.data}
                  onChange={(e) => alterar("data", e.target.value)}
                  aria-describedby={erroId}
                  aria-invalid={!!erro}
                />
              </label>
              <label htmlFor="wizard-horario">
                Horário de preferência
                <input
                  id="wizard-horario"
                  name="horario"
                  disabled={ocupado}
                  type="time"
                  required
                  className={CAMPO}
                  value={dados.horario}
                  onChange={(e) => alterar("horario", e.target.value)}
                  aria-describedby={erroId}
                  aria-invalid={!!erro}
                />
              </label>
              <p className="sm:col-span-2">
                Horário de São Paulo. A preferência está sujeita à confirmação e não reserva uma
                vaga.
              </p>
            </div>
          )}
          {etapa === 6 && (
            <fieldset className="grid gap-3">
              <legend className="mb-2">Três avisos rápidos sobre o dia da sessão.</legend>
              {AVISOS.map(({ chave, Icone, texto }) => (
                <label
                  key={chave}
                  htmlFor={`wizard-aviso-${chave}`}
                  className="flex items-start gap-3 rounded-campo border border-[var(--kolo-contorno)] p-4"
                >
                  <input
                    id={`wizard-aviso-${chave}`}
                    name={`aceite-${chave}`}
                    type="checkbox"
                    disabled={ocupado}
                    required
                    checked={dados.aceites[chave]}
                    onChange={(e) => marcarAviso(chave, e.target.checked)}
                    aria-describedby={erroId}
                    aria-invalid={!!erro && !dados.aceites[chave]}
                    className="mt-1 size-5 shrink-0 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--kolo-acao)]"
                  />
                  <Icone aria-hidden className="mt-0.5 size-5 shrink-0" />
                  <span>{texto}</span>
                </label>
              ))}
            </fieldset>
          )}
          {erro && (
            <p id="wizard-erro" role="alert" className="text-destructive">
              {erro}
            </p>
          )}
          <div className="flex flex-wrap gap-3">
            {etapa > 0 && (
              <Button type="button" variant="contorno" disabled={ocupado} onClick={voltar}>
                Voltar
              </Button>
            )}
            <Button type="submit" disabled={ocupado}>
              {ocupado ? "Revisando…" : etapa === ULTIMA ? "Revisar preferências" : "Avançar"}
            </Button>
          </div>
        </form>
      )}
    </div>
  );
}

import { Prisma } from "../../../generated/prisma/client";
import { conferirSenha, sessaoDaRequisicao } from "../../lib/auth";
import { obterPrisma } from "../../lib/prisma";
import type { DadosEndereco } from "../endereco/index";
import { validarExclusaoConta, type DadosExclusaoConta, type ErrosDe } from "../identity/index";
import { cancelarPedidoPendente } from "../orders/index";

// RN12/RNF19 (PBI-40): o cliente exclui a própria conta. Os dados pessoais são anonimizados e os
// pedidos ficam, com os mesmos valores, para o registro da venda.

export type ErroExclusao =
  "nao_autenticado" | "proibido" | "senha_incorreta" | "pedido_em_andamento" | "concorrencia";

export type ResultadoExclusao =
  | { ok: true }
  | { ok: false; erro: "invalido"; campos: ErrosDe<DadosExclusaoConta> }
  | { ok: false; erro: ErroExclusao; mensagem: string };

class Recusa extends Error {
  constructor(
    readonly codigo: ErroExclusao,
    mensagem: string,
  ) {
    super(mensagem);
  }
}

function expirada() {
  return new Recusa("nao_autenticado", "Sua sessão expirou. Entre novamente.");
}

// Pago e ainda não entregue: o ateliê precisa do endereço para concluir a entrega.
const EM_ANDAMENTO = ["PAGO", "PROCESSANDO", "ENVIADO"] as const;

export const NOME_EXCLUIDO = "Cliente excluído";

// Único (o e-mail é UK) e num domínio reservado, que nunca recebe mensagem. Libera o e-mail antigo
// para um cadastro novo.
function emailAnonimo(userId: string) {
  return `excluido-${userId}@kolo.invalid`;
}

// Cidade e UF não identificam a pessoa e servem ao registro da venda; o resto vira vazio.
function enderecoAnonimo(copia: Prisma.JsonValue): DadosEndereco {
  const { cidade, uf } = copia as DadosEndereco;
  return {
    destinatario: "",
    cep: "",
    logradouro: "",
    numero: "",
    complemento: "",
    bairro: "",
    cidade,
    uf,
  };
}

async function anonimizarCliente(tx: Prisma.TransactionClient, userId: string, agora: Date) {
  await tx.user.update({
    where: { id: userId },
    data: {
      name: NOME_EXCLUIDO,
      email: emailAnonimo(userId),
      phone: null,
      image: null,
      deletedAt: agora,
    },
  });
  // Pedido aguardando pagamento é cancelado e solta a reserva. Um pagamento aprovado depois não
  // reabre o pedido: o webhook o marca para estorno (pedido não pendente, PBI-43).
  const pendentes = await tx.order.findMany({
    where: { userId, status: "PENDENTE" },
    select: { id: true },
  });
  for (const pedido of pendentes) await cancelarPedidoPendente(tx, pedido.id);
  // Sem sessão a conta sai de todos os navegadores (as reservas da sessão vão junto, em cascata);
  // sem credencial e com o e-mail trocado, o login antigo não abre mais. O carrinho leva os itens.
  await tx.session.deleteMany({ where: { userId } });
  await tx.account.deleteMany({ where: { userId } });
  await tx.address.deleteMany({ where: { userId } });
  await tx.cart.deleteMany({ where: { userId } });
  // Hoje só a recuperação de senha usa verification, e valor guarda o id do usuário.
  await tx.verification.deleteMany({ where: { value: userId } });
  // O atendimento registrado pela equipe fica na agenda, sem a ligação com a conta.
  await tx.appointment.updateMany({ where: { userId }, data: { userId: null } });
  await tx.emailLog.updateMany({ where: { userId }, data: { recipient: emailAnonimo(userId) } });
  const pedidos = await tx.order.findMany({
    where: { userId },
    select: { id: true, addressSnapshot: true },
  });
  for (const pedido of pedidos)
    await tx.order.update({
      where: { id: pedido.id },
      data: { addressSnapshot: enderecoAnonimo(pedido.addressSnapshot) },
    });
}

export async function excluirPropriaConta(
  entrada: unknown,
  cabecalhos: Headers,
): Promise<ResultadoExclusao> {
  const validacao = validarExclusaoConta(entrada);
  if (!validacao.ok) return { ok: false, erro: "invalido", campos: validacao.campos };
  try {
    const sessao = await sessaoDaRequisicao(cabecalhos);
    if (!sessao) throw expirada();
    await obterPrisma().$transaction(async (tx) => {
      // O usuário vem só do cookie assinado. A trava do usuário vem primeiro, na mesma ordem do
      // checkout e do webhook (usuário → pedido → sessão): um pagamento aprovado ou um pedido
      // criado ao mesmo tempo termina antes, e as checagens abaixo já o enxergam.
      const dono = await tx.session.findUnique({
        where: { token: sessao.token },
        select: { userId: true },
      });
      if (!dono) throw expirada();
      await tx.$queryRaw`SELECT id FROM "user" WHERE id = ${dono.userId}::uuid FOR UPDATE`;
      const atual = await tx.session.findUnique({
        where: { token: sessao.token },
        include: { user: true },
      });
      if (!atual || atual.expiresAt <= new Date()) throw expirada();
      if (
        atual.user.role !== "CLIENTE" ||
        atual.user.status !== "ATIVO" ||
        atual.user.deletedAt !== null
      )
        throw new Recusa(
          "proibido",
          "Só a conta de cliente pode ser excluída pelo site. Fale com o ateliê.",
        );
      const credencial = await tx.account.findFirst({
        where: { userId: atual.userId, provider: "credential" },
      });
      if (
        !credencial?.passwordHash ||
        !(await conferirSenha(credencial.passwordHash, validacao.dados.senha))
      )
        throw new Recusa("senha_incorreta", "Senha atual incorreta.");
      const emAndamento = await tx.order.count({
        where: { userId: atual.userId, deletedAt: null, status: { in: [...EM_ANDAMENTO] } },
      });
      if (emAndamento > 0)
        throw new Recusa(
          "pedido_em_andamento",
          "Você tem um pedido a caminho. Aguarde a entrega para excluir a conta ou fale com o ateliê.",
        );
      await anonimizarCliente(tx, atual.userId, new Date());
    });
    return { ok: true };
  } catch (erro) {
    if (erro instanceof Recusa) return { ok: false, erro: erro.codigo, mensagem: erro.message };
    // P2034: impasse de travas. P2028: a transação expirou (5 s) esperando a trava do usuário, presa
    // por um checkout ou webhook demorado. Nos dois casos nada foi gravado e dá para tentar de novo.
    if (
      erro instanceof Prisma.PrismaClientKnownRequestError &&
      (erro.code === "P2034" || erro.code === "P2028")
    )
      return {
        ok: false,
        erro: "concorrencia",
        mensagem: "Sua conta mudou enquanto excluíamos. Tente novamente.",
      };
    throw erro;
  }
}

import { sessaoDaRequisicao } from "../../lib/auth";
import { obterPrisma } from "../../lib/prisma";
import type { DestinoImagem } from "./chave";

export type ResultadoAutorizacao =
  { ok: true } | { ok: false; erro: "nao_autenticado" | "proibido" | "artista_inexistente" };

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

// O papel, a situação e o vínculo com o artista são relidos no banco a cada pedido: a
// sessão só identifica quem pede, nunca o que ele pode.
export async function autorizarUpload(
  cabecalhos: Headers,
  alvo: { destino: DestinoImagem; artistId: string },
): Promise<ResultadoAutorizacao> {
  const sessao = await sessaoDaRequisicao(cabecalhos);
  if (!sessao) return { ok: false, erro: "nao_autenticado" };
  const prisma = obterPrisma();
  const atual = await prisma.session.findUnique({
    where: { token: sessao.token },
    include: { user: { include: { artist: true } } },
  });
  if (!atual || atual.expiresAt <= new Date()) return { ok: false, erro: "nao_autenticado" };
  const { user } = atual;
  if (user.status !== "ATIVO" || user.deletedAt !== null) return { ok: false, erro: "proibido" };
  // ESCOPO §7 e RN10: obras são só do ADMIN; o artista envia apenas ao próprio portfólio.
  if (user.role === "ARTISTA") {
    return alvo.destino === "portfolio" && user.artist?.id === alvo.artistId
      ? { ok: true }
      : { ok: false, erro: "proibido" };
  }
  if (user.role !== "ADMIN") return { ok: false, erro: "proibido" };
  const existe =
    UUID.test(alvo.artistId) &&
    (await prisma.artist.findUnique({ where: { id: alvo.artistId }, select: { id: true } })) !==
      null;
  return existe ? { ok: true } : { ok: false, erro: "artista_inexistente" };
}

import { createHash, randomBytes } from "node:crypto";
import { z } from "zod";
import type { Prisma } from "../../../generated/prisma/client";
import { sessaoDaRequisicao } from "../../lib/auth";
import { obterPrisma } from "../../lib/prisma";
import { chaveMiniatura } from "../media/index";
import { obraDisponivel, quantidadeValida, resumirCarrinho } from "./regras";

// Quem é o dono do carrinho: a sessão (conta) ou o token do cookie do visitante.
export type ContextoCarrinho = { cabecalhos: Headers; tokenVisitante: string | null };
export type ResultadoCarrinho<T = undefined> =
  { ok: true; dados: T } | { ok: false; erro: string; mensagem: string };

class ErroCarrinho extends Error {
  constructor(
    public codigo: string,
    mensagem: string,
  ) {
    super(mensagem);
  }
}

const schemaId = z.uuid("Obra inválida.");
const schemaQuantidade = z
  .number()
  .int("Escolha uma quantidade inteira.")
  .min(1, "Escolha pelo menos 1 unidade.")
  .max(999);
const schemaAdicionar = z.object({ obraId: schemaId, quantidade: schemaQuantidade.default(1) });
const schemaAlterar = z.object({ obraId: schemaId, quantidade: schemaQuantidade });

function validar<T>(schema: z.ZodType<T>, entrada: unknown): T {
  const resultado = schema.safeParse(entrada);
  if (!resultado.success)
    throw new ErroCarrinho("invalido", resultado.error.issues.map((i) => i.message).join(" "));
  return resultado.data;
}

async function executar<T>(acao: () => Promise<T>): Promise<ResultadoCarrinho<T>> {
  try {
    return { ok: true, dados: await acao() };
  } catch (erro) {
    if (erro instanceof ErroCarrinho)
      return { ok: false, erro: erro.codigo, mensagem: erro.message };
    console.error("Falha no carrinho", erro instanceof Error ? erro.name : "erro desconhecido");
    return {
      ok: false,
      erro: "falha",
      mensagem: "Não foi possível atualizar o carrinho agora. Tente novamente.",
    };
  }
}

// O cookie leva o token; o banco guarda só o hash, como o rate limit do login.
export function hashDoToken(token: string): string {
  return createHash("sha256").update(token).digest("hex");
}

// A sessão diz quem pede; a situação da conta é relida no banco.
export async function usuarioDaSessao(cabecalhos: Headers): Promise<string | null> {
  return (await sessaoAtiva(cabecalhos))?.userId ?? null;
}

// O checkout precisa também do id da sessão, a quem a reserva pertence (PBI-25).
export async function sessaoAtiva(
  cabecalhos: Headers,
): Promise<{ userId: string; sessaoId: string } | null> {
  const sessao = await sessaoDaRequisicao(cabecalhos);
  if (!sessao) return null;
  const atual = await obterPrisma().session.findUnique({
    where: { token: sessao.token },
    include: { user: true },
  });
  if (
    !atual ||
    atual.expiresAt <= new Date() ||
    atual.user.status !== "ATIVO" ||
    atual.user.deletedAt !== null
  )
    return null;
  return { userId: atual.userId, sessaoId: atual.id };
}

type Dono = { userId: string } | { cookieToken: string };

async function donoDoContexto(contexto: ContextoCarrinho): Promise<Dono | null> {
  const userId = await usuarioDaSessao(contexto.cabecalhos);
  if (userId) return { userId };
  return contexto.tokenVisitante ? { cookieToken: hashDoToken(contexto.tokenVisitante) } : null;
}

export function carrinhoDo(tx: Prisma.TransactionClient, dono: Dono) {
  return "userId" in dono
    ? tx.cart.findFirst({ where: { userId: dono.userId }, orderBy: { updatedAt: "desc" } })
    : tx.cart.findUnique({ where: { cookieToken: dono.cookieToken } });
}

function disponivel(obra: {
  status: "RASCUNHO" | "DISPONIVEL" | "ESGOTADA";
  deletedAt: Date | null;
  stockQuantity: number;
}) {
  return obraDisponivel({
    situacao: obra.status,
    arquivada: obra.deletedAt !== null,
    estoque: obra.stockQuantity,
  });
}

// RF11: o carrinho não reserva estoque; só confere que a quantidade cabe no estoque atual.
export function adicionarAoCarrinho(entrada: unknown, contexto: ContextoCarrinho) {
  return executar(async () => {
    const { obraId, quantidade } = validar(schemaAdicionar, entrada);
    const dono = await donoDoContexto(contexto);
    return obterPrisma().$transaction(async (tx) => {
      const obra = await tx.artwork.findUnique({ where: { id: obraId } });
      if (!obra || !disponivel(obra))
        throw new ErroCarrinho("indisponivel", "Esta obra não está disponível para compra.");
      let tokenNovo: string | null = null;
      let carrinho = dono ? await carrinhoDo(tx, dono) : null;
      if (!carrinho) {
        if (dono && "userId" in dono)
          carrinho = await tx.cart.create({ data: { userId: dono.userId } });
        else {
          // Visitante sem carrinho (ou com cookie de um carrinho que não existe mais).
          tokenNovo = randomBytes(32).toString("base64url");
          carrinho = await tx.cart.create({ data: { cookieToken: hashDoToken(tokenNovo) } });
        }
      }
      const chave = { cartId_artworkId: { cartId: carrinho.id, artworkId: obraId } };
      const existente = await tx.cartItem.findUnique({ where: chave });
      const total = (existente?.quantity ?? 0) + quantidade;
      if (!quantidadeValida(total, obra.stockQuantity))
        throw new ErroCarrinho(
          "quantidade_invalida",
          existente
            ? "Você já tem no carrinho todas as unidades disponíveis desta obra."
            : `Só há ${obra.stockQuantity} ${obra.stockQuantity === 1 ? "unidade" : "unidades"} desta obra.`,
        );
      await tx.cartItem.upsert({
        where: chave,
        create: { cartId: carrinho.id, artworkId: obraId, quantity: total },
        update: { quantity: total },
      });
      await tx.cart.update({ where: { id: carrinho.id }, data: { updatedAt: new Date() } });
      return { tokenNovo };
    });
  });
}

export function alterarQuantidade(entrada: unknown, contexto: ContextoCarrinho) {
  return executar(async () => {
    const { obraId, quantidade } = validar(schemaAlterar, entrada);
    const dono = await donoDoContexto(contexto);
    await obterPrisma().$transaction(async (tx) => {
      const carrinho = dono ? await carrinhoDo(tx, dono) : null;
      const chave = { cartId_artworkId: { cartId: carrinho?.id ?? "", artworkId: obraId } };
      const item = carrinho
        ? await tx.cartItem.findUnique({ where: chave, include: { artwork: true } })
        : null;
      if (!item) throw new ErroCarrinho("nao_encontrado", "Esta obra não está no seu carrinho.");
      if (!disponivel(item.artwork))
        throw new ErroCarrinho(
          "indisponivel",
          "Esta obra não está mais disponível. Remova-a do carrinho.",
        );
      if (!quantidadeValida(quantidade, item.artwork.stockQuantity))
        throw new ErroCarrinho(
          "quantidade_invalida",
          `Escolha de 1 a ${item.artwork.stockQuantity} unidades.`,
        );
      await tx.cartItem.update({ where: { id: item.id }, data: { quantity: quantidade } });
      await tx.cart.update({ where: { id: item.cartId }, data: { updatedAt: new Date() } });
    });
  });
}

export function removerDoCarrinho(obraId: unknown, contexto: ContextoCarrinho) {
  return executar(async () => {
    const id = validar(schemaId, obraId);
    const dono = await donoDoContexto(contexto);
    await obterPrisma().$transaction(async (tx) => {
      const carrinho = dono ? await carrinhoDo(tx, dono) : null;
      if (carrinho) await tx.cartItem.deleteMany({ where: { cartId: carrinho.id, artworkId: id } });
    });
  });
}

// Preço, disponibilidade e total vêm sempre do banco, nunca do navegador.
export function lerCarrinho(contexto: ContextoCarrinho) {
  return executar(async () => {
    const dono = await donoDoContexto(contexto);
    const carrinho = dono ? await carrinhoDo(obterPrisma(), dono) : null;
    const itens = carrinho
      ? await obterPrisma().cartItem.findMany({
          where: { cartId: carrinho.id },
          include: {
            artwork: {
              include: {
                artist: { include: { user: true } },
                images: { where: { primary: true }, take: 1 },
              },
            },
          },
          orderBy: { addedAt: "asc" },
        })
      : [];
    const linhas = itens.map(({ artwork: obra, quantity }) => {
      const principal = obra.images[0];
      return {
        obraId: obra.id,
        titulo: obra.title,
        slug: obra.slug,
        artistaNome: obra.artist.user.name,
        precoCentavos: obra.priceCents,
        quantidade: quantity,
        estoque: obra.stockQuantity,
        disponivel: disponivel(obra),
        chaveMiniatura: principal ? chaveMiniatura(principal.url) : null,
        textoAlternativo: principal?.altText ?? obra.title,
      };
    });
    return { itens: linhas, ...resumirCarrinho(linhas) };
  });
}

import { randomBytes } from "node:crypto";
import { z } from "zod";
import { Prisma } from "../../../generated/prisma/client";
import { obterPrisma } from "../../lib/prisma";
import { validarEndereco, type DadosEndereco } from "../endereco/index";
import { lerCarrinho, sessaoAtiva, type ContextoCarrinho } from "./carrinho";
import { calcularFrete, MODALIDADES, type ModalidadeFrete } from "./frete";
import { numeroDoPedido } from "./regras";
import { reservarItens } from "./reserva";
import { cancelarPedidoPendente } from "./transicoes";

// PBI-26: retirada no ateliê, sem custo. PBI-42: entrega no endereço, com o frete de calcularFrete.
export type Modalidade = ModalidadeFrete;

export type ItemCheckout = {
  obraId: string;
  titulo: string;
  artistaNome: string;
  quantidade: number;
  precoCentavos: number;
  chaveMiniatura: string | null;
  textoAlternativo: string;
};
export type ResumoCheckout = {
  itens: ItemCheckout[];
  endereco: DadosEndereco;
  modalidade: Modalidade;
  subtotalCentavos: number;
  freteCentavos: number;
  totalCentavos: number;
  // PBI-42: o frete de cada modalidade para o endereço do cliente; null é indisponível.
  modalidades: { modalidade: Modalidade; freteCentavos: number | null }[];
};
export type ResultadoCheckout<T> =
  | { ok: true; dados: T }
  | {
      ok: false;
      erro: "nao_autenticado" | "carrinho_vazio" | "sem_endereco" | "falha";
      mensagem: string;
    }
  | { ok: false; erro: "indisponivel"; obras: string[]; mensagem: string };

export type ResultadoFinalizar =
  | ResultadoCheckout<{ numero: string; expiraEm: Date }>
  | { ok: false; erro: "invalido"; mensagem: string }
  | { ok: false; erro: "pendente"; numero: string; mensagem: string };

export type OpcoesFinalizar = { agora?: Date; gerarNumero?: (agora: Date) => string };

type Comprador = { userId: string; sessaoId: string };

// RF12/RN07: itens, preços e endereço vêm do banco; o total é calculado aqui, em centavos.
export async function resumoCheckout(
  contexto: ContextoCarrinho,
  agora: Date = new Date(),
): Promise<ResultadoCheckout<ResumoCheckout>> {
  const montado = await montarResumo(contexto, agora, "RETIRADA");
  return montado.ok ? { ok: true, dados: montado.dados.resumo } : montado;
}

// O resumo usa o frete da modalidade escolhida; a página abre na retirada.
async function montarResumo(
  contexto: ContextoCarrinho,
  agora: Date,
  modalidade: Modalidade,
): Promise<
  ResultadoCheckout<{ resumo: ResumoCheckout; comprador: Comprador; freteCentavos: number | null }>
> {
  const sessao = await sessaoAtiva(contexto.cabecalhos);
  if (!sessao)
    return { ok: false, erro: "nao_autenticado", mensagem: "Entre na sua conta para comprar." };
  const { userId, sessaoId } = sessao;
  const carrinho = await lerCarrinho(contexto);
  if (!carrinho.ok) return { ok: false, erro: "falha", mensagem: carrinho.mensagem };
  if (carrinho.dados.itens.length === 0)
    return { ok: false, erro: "carrinho_vazio", mensagem: "Seu carrinho está vazio." };

  // RN02/RN11: a obra precisa seguir à venda, e as unidades presas por outros clientes não
  // contam. As reservas do próprio cliente, em qualquer sessão, são de um pedido dele: o
  // abandonado o finalizar cancela, e o com pagamento em aberto o leva de volta ao pedido.
  // A conferência com trava fica com reservarItens, dentro da transação.
  const presas = await obterPrisma().artworkReservation.groupBy({
    by: ["artworkId"],
    where: {
      artworkId: { in: carrinho.dados.itens.map((i) => i.obraId) },
      expiresAt: { gt: agora },
      session: { userId: { not: userId } },
    },
    _sum: { quantity: true },
  });
  const presasDe = (id: string) => presas.find((r) => r.artworkId === id)?._sum.quantity ?? 0;
  const indisponiveis = carrinho.dados.itens
    .filter((i) => !i.disponivel || i.estoque - presasDe(i.obraId) < i.quantidade)
    .map((i) => i.obraId);
  if (indisponiveis.length > 0)
    return {
      ok: false,
      erro: "indisponivel",
      obras: indisponiveis,
      mensagem: "Algumas obras do carrinho não estão mais disponíveis nessa quantidade.",
    };
  const linha = await obterPrisma().address.findUnique({ where: { userId } });
  const endereco = linha
    ? validarEndereco({
        destinatario: linha.recipient,
        cep: linha.postalCode,
        logradouro: linha.street,
        numero: linha.number,
        complemento: linha.complement ?? "",
        bairro: linha.neighborhood,
        cidade: linha.city,
        uf: linha.state,
      })
    : null;
  if (!endereco?.ok)
    return {
      ok: false,
      erro: "sem_endereco",
      mensagem: "Cadastre um endereço válido na sua conta antes de finalizar.",
    };

  const itens = carrinho.dados.itens.map((item) => ({
    obraId: item.obraId,
    titulo: item.titulo,
    artistaNome: item.artistaNome,
    quantidade: item.quantidade,
    precoCentavos: item.precoCentavos,
    chaveMiniatura: item.chaveMiniatura,
    textoAlternativo: item.textoAlternativo,
  }));
  const subtotalCentavos = itens.reduce((soma, i) => soma + i.precoCentavos * i.quantidade, 0);
  const modalidades = MODALIDADES.map((m) => ({
    modalidade: m,
    freteCentavos: calcularFrete(m, endereco.dados),
  }));
  const freteCentavos = calcularFrete(modalidade, endereco.dados);
  return {
    ok: true,
    dados: {
      resumo: {
        itens,
        endereco: endereco.dados,
        modalidade,
        subtotalCentavos,
        freteCentavos: freteCentavos ?? 0,
        totalCentavos: subtotalCentavos + (freteCentavos ?? 0),
        modalidades,
      },
      comprador: { userId, sessaoId },
      freteCentavos,
    },
  };
}

// O formulário só escolhe a modalidade. Preço, total, quantidade e endereço que venham junto
// são descartados pelo schema: o pedido sai do banco (RN07).
const schemaFinalizar = z.object({
  modalidade: z.enum(MODALIDADES, { error: "Escolha uma forma de entrega válida." }),
});

// O número é sorteado; se repetir um existente, a transação inteira cai e roda de novo.
const TENTATIVAS_NUMERO = 5;
const FALHA_FINALIZAR = {
  ok: false,
  erro: "falha",
  mensagem: "Não foi possível finalizar a compra agora. Tente novamente.",
} as const;

// Recusa no meio da transação: lançada para o Prisma desfazer o que já foi feito (o cancelamento
// do pedido abandonado, por exemplo) e devolvida como resultado fora dela.
class Recusa extends Error {
  constructor(public resultado: ResultadoFinalizar) {
    super("recusa no checkout");
  }
}

// Nesta transação o único UNIQUE que pode falhar é o número do pedido.
function numeroRepetido(erro: unknown): boolean {
  return erro instanceof Prisma.PrismaClientKnownRequestError && erro.code === "P2002";
}

// RF12/RF15: o pedido PENDENTE e a reserva de 10 minutos nascem na mesma transação; se um
// falha, o outro não fica. O pedido guarda cópias de endereço, títulos e preços.
export async function finalizarCompra(
  entrada: unknown,
  contexto: ContextoCarrinho,
  opcoes: OpcoesFinalizar = {},
): Promise<ResultadoFinalizar> {
  const agora = opcoes.agora ?? new Date();
  const gerarNumero = opcoes.gerarNumero ?? ((data: Date) => numeroDoPedido(data, randomBytes(6)));
  const validado = schemaFinalizar.safeParse(entrada);
  if (!validado.success)
    return {
      ok: false,
      erro: "invalido",
      mensagem: validado.error.issues.map((i) => i.message).join(" "),
    };
  const montado = await montarResumo(contexto, agora, validado.data.modalidade);
  if (!montado.ok) return montado;
  const { resumo, comprador } = montado.dados;
  if (montado.dados.freteCentavos === null)
    return {
      ok: false,
      erro: "invalido",
      mensagem: "A entrega não está disponível para o seu endereço. Escolha a retirada no ateliê.",
    };

  const criar = async (tx: Prisma.TransactionClient): Promise<ResultadoFinalizar> => {
    // Cliques simultâneos da mesma conta se enfileiram aqui: cada um vê o pedido que o anterior
    // criou e o cancela, e sobra um PENDENTE só. Ordem das travas: usuário → sessão → obras.
    await tx.$queryRaw`SELECT id FROM "user" WHERE id = ${comprador.userId}::uuid FOR UPDATE`;

    // RN06: com Pix ou boleto em aberto, o cliente volta ao pedido (pagar ou cancelar); um novo
    // checkout não o substitui nem mexe na reserva prorrogada.
    const emAberto = await tx.order.findFirst({
      where: {
        userId: comprador.userId,
        status: "PENDENTE",
        payments: { some: { status: "PENDENTE" } },
      },
    });
    if (emAberto)
      throw new Recusa({
        ok: false,
        erro: "pendente",
        numero: emAberto.number,
        mensagem: "Você já tem um pedido aguardando pagamento.",
      });

    // Pedido PENDENTE sem pagamento em aberto foi abandonado (ou o pagamento foi recusado): o
    // novo checkout o cancela e solta as unidades que ele segurava, mesmo que tenham sido
    // reservadas em outra sessão da conta.
    const abandonados = await tx.order.findMany({
      where: {
        userId: comprador.userId,
        status: "PENDENTE",
        payments: { none: { status: "PENDENTE" } },
      },
    });
    // Só o que ainda está PENDENTE: um aviso de pagamento aprovado que terminou entre a leitura
    // e esta escrita não pode ter o pedido pago cancelado por cima (PBI-28).
    for (const abandonado of abandonados) await cancelarPedidoPendente(tx, abandonado.id);

    const reserva = await reservarItens(
      comprador.sessaoId,
      resumo.itens.map((i) => ({ obraId: i.obraId, quantidade: i.quantidade })),
      agora,
      tx,
    );
    if (!reserva.ok)
      throw new Recusa(
        reserva.erro === "indisponivel"
          ? {
              ok: false,
              erro: "indisponivel",
              obras: reserva.obras,
              mensagem: "Algumas obras do carrinho não estão mais disponíveis nessa quantidade.",
            }
          : { ok: false, erro: "falha", mensagem: "Não foi possível reservar as obras agora." },
      );

    const numero = gerarNumero(agora);
    await tx.order.create({
      data: {
        number: numero,
        userId: comprador.userId,
        sessionId: comprador.sessaoId,
        deliveryMethod: resumo.modalidade,
        subtotalCents: resumo.subtotalCentavos,
        shippingCents: resumo.freteCentavos,
        totalCents: resumo.totalCentavos,
        addressSnapshot: resumo.endereco,
        createdAt: agora,
        items: {
          create: resumo.itens.map((i) => ({
            artworkId: i.obraId,
            titleSnapshot: i.titulo,
            priceCents: i.precoCentavos,
            quantity: i.quantidade,
          })),
        },
      },
    });
    return { ok: true, dados: { numero, expiraEm: reserva.dados.expiraEm } };
  };

  for (let tentativa = 1; tentativa <= TENTATIVAS_NUMERO; tentativa++) {
    try {
      return await obterPrisma().$transaction(criar);
    } catch (erro) {
      if (erro instanceof Recusa) return erro.resultado;
      if (numeroRepetido(erro) && tentativa < TENTATIVAS_NUMERO) continue;
      console.error(
        "Falha ao finalizar a compra",
        erro instanceof Error ? erro.name : "erro desconhecido",
      );
      return FALHA_FINALIZAR;
    }
  }
  return FALHA_FINALIZAR;
}

import { obterPrisma } from "../../lib/prisma";
import type { DadosEndereco } from "../endereco/index";
import { sessaoAtiva, type ContextoCarrinho } from "./carrinho";
import type { Modalidade } from "./checkout";

export type SituacaoPedido =
  "PENDENTE" | "PAGO" | "PROCESSANDO" | "ENVIADO" | "ENTREGUE" | "CANCELADO";

export type PedidoResumo = {
  numero: string;
  situacao: SituacaoPedido;
  modalidade: Modalidade;
  criadoEm: Date;
  // Até quando as unidades do pedido pendente seguem presas (null se não há reserva ativa).
  reservaExpiraEm: Date | null;
  itens: { obraId: string; titulo: string; precoCentavos: number; quantidade: number }[];
  endereco: DadosEndereco;
  subtotalCentavos: number;
  freteCentavos: number;
  totalCentavos: number;
};

// RN01: o pedido só existe para o dono. Para outro cliente ou visitante, a resposta é a mesma
// de um número que não existe, sem revelar que o pedido existe.
export async function lerPedido(
  numero: unknown,
  contexto: ContextoCarrinho,
  agora: Date = new Date(),
): Promise<PedidoResumo | null> {
  if (typeof numero !== "string" || numero.length === 0 || numero.length > 32) return null;
  const sessao = await sessaoAtiva(contexto.cabecalhos);
  if (!sessao) return null;
  const prisma = obterPrisma();
  const pedido = await prisma.order.findFirst({
    where: { number: numero, userId: sessao.userId, deletedAt: null },
    include: { items: { orderBy: { titleSnapshot: "asc" } } },
  });
  if (!pedido) return null;

  const reserva =
    pedido.status === "PENDENTE" && pedido.sessionId
      ? await prisma.artworkReservation.aggregate({
          where: {
            sessionId: pedido.sessionId,
            artworkId: { in: pedido.items.map((i) => i.artworkId) },
            expiresAt: { gt: agora },
          },
          _max: { expiresAt: true },
        })
      : null;
  return {
    numero: pedido.number,
    situacao: pedido.status,
    modalidade: pedido.deliveryMethod,
    criadoEm: pedido.createdAt,
    reservaExpiraEm: reserva?._max.expiresAt ?? null,
    itens: pedido.items.map((i) => ({
      obraId: i.artworkId,
      titulo: i.titleSnapshot,
      precoCentavos: i.priceCents,
      quantidade: i.quantity,
    })),
    // Cópia gravada pelo próprio checkout, já validada por validarEndereco.
    endereco: pedido.addressSnapshot as DadosEndereco,
    subtotalCentavos: pedido.subtotalCents,
    freteCentavos: pedido.shippingCents,
    totalCentavos: pedido.totalCents,
  };
}

import { obterPrisma } from "../../lib/prisma";
import { lerPedido, type ContextoCarrinho } from "../orders/index";
import { prazoParaPagar } from "./cliente";
import { montarPreferencia, type CorpoPreferencia } from "./preferencia";

// Porta do provedor: pede a preferência (recebe a URL do checkout hospedado) e consulta um
// pagamento pelo id do aviso (o webhook só confia nessa resposta, RN05).
export type GatewayPagamento = {
  criarPreferencia(corpo: CorpoPreferencia): Promise<{ url: string }>;
  // null: o pagamento não existe para esta conta (404).
  consultarPagamento(id: string): Promise<unknown | null>;
  // PBI-43: estorno total. A chave de idempotência faz a nova tentativa não estornar de novo.
  estornarPagamento(id: string, chaveIdempotencia: string): Promise<void>;
  // PBI-43: cancela o Pix ou boleto que ainda não foi pago.
  cancelarPagamento(id: string): Promise<void>;
};

export type OpcoesPagamento = {
  gateway: Pick<GatewayPagamento, "criarPreferencia">;
  agora?: Date;
  appUrl?: string;
};

export type ResultadoPagamento =
  | { ok: true; dados: { url: string } }
  | {
      ok: false;
      erro:
        "nao_encontrado" | "nao_pendente" | "pagamento_em_aberto" | "reserva_expirada" | "falha";
      mensagem: string;
    };

const NAO_ENCONTRADO = {
  ok: false,
  erro: "nao_encontrado",
  mensagem: "Pedido não encontrado.",
} as const;

// RF13: só abre o Checkout Pro. Confirmar o pedido e baixar o estoque é do webhook (PBI-28),
// nunca deste fluxo nem da volta do navegador (RN05).
export async function iniciarPagamento(
  numero: unknown,
  contexto: ContextoCarrinho,
  opcoes: OpcoesPagamento,
): Promise<ResultadoPagamento> {
  const agora = opcoes.agora ?? new Date();
  const pedido = await lerPedido(numero, contexto, agora);
  if (!pedido) return NAO_ENCONTRADO;
  if (pedido.situacao !== "PENDENTE")
    return { ok: false, erro: "nao_pendente", mensagem: "Este pedido não aguarda pagamento." };
  // RN06: Pix ou boleto emitido segura as unidades até vencer; outra cobrança do mesmo pedido
  // abriria a porta para pagar duas vezes.
  const emAberto = await obterPrisma().payment.count({
    where: { status: "PENDENTE", order: { number: pedido.numero } },
  });
  if (emAberto > 0)
    return {
      ok: false,
      erro: "pagamento_em_aberto",
      mensagem: "Este pedido já tem um pagamento aguardando confirmação.",
    };
  // RN03: sem unidades presas, pagar agora poderia vender o que já voltou à vitrine.
  if (!pedido.reservaExpiraEm)
    return {
      ok: false,
      erro: "reserva_expirada",
      mensagem: "A reserva das obras expirou. Finalize de novo pelo carrinho.",
    };
  // RN06: nos minutos finais da reserva o checkout já fechou (FOLGA_PAGAMENTO_MS), para um Pix ou
  // boleto gerado no último instante ainda encontrar a reserva quando o webhook chegar.
  const prazo = prazoParaPagar(pedido.reservaExpiraEm);
  if (!prazo || prazo <= agora)
    return {
      ok: false,
      erro: "reserva_expirada",
      mensagem: "O prazo para pagar este pedido acabou. Finalize de novo pelo carrinho.",
    };
  const preferencia = montarPreferencia(pedido, opcoes.appUrl ?? process.env.APP_URL ?? "");
  if (!preferencia.ok) return { ok: false, erro: "falha", mensagem: preferencia.mensagem };
  try {
    return { ok: true, dados: await opcoes.gateway.criarPreferencia(preferencia.dados) };
  } catch (erro) {
    // Só o tipo e o status HTTP: a mensagem e a resposta do provedor podem trazer dados do pedido
    // ou da conta.
    const status =
      erro instanceof Error && "status" in erro && typeof erro.status === "number"
        ? erro.status
        : null;
    console.error(
      "Falha ao criar a preferência no Mercado Pago",
      erro instanceof Error ? erro.name : "erro desconhecido",
      status,
    );
    return {
      ok: false,
      erro: "falha",
      mensagem: "Não foi possível abrir o pagamento agora. Tente de novo em instantes.",
    };
  }
}

import { randomUUID } from "node:crypto";
import { z } from "zod";
import type { Prisma, RefundReason } from "../../../generated/prisma/client";
import { obterPrisma } from "../../lib/prisma";
import {
  cancelarPedidoPendente,
  confirmarPedidoPago,
  PRAZO_RESERVA_MS,
  prorrogarReserva,
  voltarReservaAoPrazo,
} from "../orders/index";
import { assinaturaValida } from "./assinatura";
import { prazoParaPagar } from "./cliente";
import { lerPagamento, PROVEDOR, type PagamentoLido, type SituacaoPagamento } from "./leitura";

// Porta da consulta: o webhook só confia na situação que a API de pagamentos devolve (RN05).
export type ConsultaPagamento = { consultarPagamento(id: string): Promise<unknown | null> };

// O corpo é lido sob demanda: só depois de a assinatura (que depende só da URL e dos cabeçalhos)
// conferir, para um POST anônimo não custar o parse do corpo.
export type RequisicaoNotificacao = {
  url: string;
  cabecalhos: Headers;
  lerCorpo(): Promise<unknown>;
};
export type OpcoesNotificacao = { gateway: ConsultaPagamento; segredo: string; agora?: Date };
export type RespostaNotificacao = { status: 200 | 401 | 500 };

const schemaCorpo = z.object({
  id: z.union([z.string(), z.number()]).nullish(),
  type: z.string().nullish(),
});

type Tx = Prisma.TransactionClient;

// Pendente vira aprovado ou recusado, que só viram estornado.
const ORDEM: Record<SituacaoPagamento, number> = {
  PENDENTE: 0,
  APROVADO: 1,
  RECUSADO: 1,
  ESTORNADO: 2,
};

type Dono = { id: string; userId: string };
type Pedido = Prisma.OrderGetPayload<{ include: { items: true } }>;
type Item = { obraId: string; quantidade: number };

// PBI-43: o pagamento aprovado que não pagou o pedido (ou pagou sem unidade livre) fica marcado
// para o admin estornar. O log continua para quem acompanha a operação.
async function marcarEstorno(
  tx: Tx,
  pagamento: PagamentoLido,
  motivo: RefundReason,
  mensagem: string,
  numero: string,
) {
  await tx.payment.update({
    where: { provider_externalId: { provider: PROVEDOR, externalId: pagamento.idExterno } },
    data: { refundReason: motivo },
  });
  console.error(mensagem, numero, pagamento.idExterno);
}

// RF14/RN05: com o pagamento aprovado, o pedido vai a PAGO, o estoque baixa e as obras saem do
// carrinho, na mesma transação do evento (RNF11).
async function aprovar(tx: Tx, pedido: Pedido, pagamento: PagamentoLido, agora: Date) {
  // Pedido cancelado (um novo checkout o substituiu) ou já pago por outro pagamento: não reabre
  // nem paga de novo; o dinheiro volta pelo estorno (PBI-43).
  if (pedido.status !== "PENDENTE")
    return marcarEstorno(
      tx,
      pagamento,
      "PEDIDO_NAO_PENDENTE",
      "Pagamento aprovado de pedido que não aguardava pagamento: estornar (PBI-43)",
      pedido.number,
    );
  // RN07: só paga o pedido o pagamento que cobriu exatamente o total gravado, em reais.
  if (pagamento.valorCentavos !== pedido.totalCents || pagamento.moeda !== "BRL")
    return marcarEstorno(
      tx,
      pagamento,
      "VALOR_DIVERGENTE",
      "Pagamento aprovado com valor diferente do pedido: estornar (PBI-43)",
      pedido.number,
    );
  // RN06: o cliente pagou, então o pedido fica pago; sem unidade livre, quem resolve é o
  // estorno (PBI-43).
  const confirmado = await confirmarPedidoPago(tx, pedido.id, agora);
  if (confirmado.ok && !confirmado.estoqueBaixado)
    await marcarEstorno(
      tx,
      pagamento,
      "SEM_ESTOQUE",
      "Pagamento aprovado sem unidade livre: estornar (PBI-43)",
      pedido.number,
    );
}

// RN06: Pix ou boleto emitido segura as unidades até o vencimento do meio de pagamento.
async function prorrogar(
  tx: Tx,
  pedido: Pedido,
  itens: Item[],
  pagamento: PagamentoLido,
  agora: Date,
) {
  if (pagamento.meio !== "PIX" && pagamento.meio !== "BOLETO") return;
  if (pedido.status !== "PENDENTE" || !pedido.sessionId || !pagamento.venceEm) return;
  const prorrogada = await prorrogarReserva(pedido.sessionId, itens, pagamento.venceEm, agora, tx);
  // Sem reserva (venceu, ou o carrinho mudou), a aprovação cai na reconciliação da baixa.
  if (!prorrogada.ok)
    console.error(
      "Reserva não prorrogada para o pagamento pendente",
      pedido.number,
      pagamento.idExterno,
      prorrogada.erro,
    );
}

// RN06: Pix ou boleto que venceu (ou foi cancelado) sem pagar encerra o pedido e devolve as
// unidades. Cartão recusado não: o cliente pode tentar de novo enquanto a reserva durar.
// PBI-43: enquanto a preferência ainda aceita pagamento (prazo do checkout), o pedido também
// fica aberto, senão um cartão pago em seguida chegaria para um pedido cancelado.
async function encerrar(tx: Tx, pedido: Pedido, pagamento: PagamentoLido, agora: Date) {
  if (pagamento.meio !== "PIX" && pagamento.meio !== "BOLETO") return;
  if (pedido.status !== "PENDENTE") return;
  const outroEmAberto = await tx.payment.count({
    where: {
      orderId: pedido.id,
      externalId: { not: pagamento.idExterno },
      status: { in: ["PENDENTE", "APROVADO"] },
    },
  });
  if (outroEmAberto > 0) return;
  const prazo = prazoParaPagar(new Date(pedido.createdAt.getTime() + PRAZO_RESERVA_MS));
  if (prazo && agora < prazo) return voltarReservaAoPrazo(tx, pedido.id);
  await cancelarPedidoPendente(tx, pedido.id);
}

async function aplicar(
  tx: Tx,
  pagamento: PagamentoLido,
  dono: Dono,
  idEvento: string,
  agora: Date,
) {
  // RNF11: aviso já visto não faz nada. Um reenvio simultâneo espera aqui o primeiro terminar a
  // transação; se o primeiro foi desfeito, este processa no lugar dele.
  const { count } = await tx.webhookEvent.createMany({
    data: { eventId: idEvento, source: PROVEDOR, payload: pagamento.registro, processedAt: agora },
    skipDuplicates: true,
  });
  if (count === 0) return;
  // Mesma ordem de travas do checkout (usuário → pedido → sessão → obras): avisos do mesmo
  // pedido, e um checkout da mesma conta, se enfileiram aqui.
  await tx.$queryRaw`SELECT id FROM "user" WHERE id = ${dono.userId}::uuid FOR UPDATE`;
  await tx.$queryRaw`SELECT id FROM "order" WHERE id = ${dono.id}::uuid FOR UPDATE`;
  const pedido = await tx.order.findUniqueOrThrow({
    where: { id: dono.id },
    include: { items: true },
  });

  const chave = { provider: PROVEDOR, externalId: pagamento.idExterno };
  const anterior = await tx.payment.findUnique({ where: { provider_externalId: chave } });
  // Avisos fora de ordem: a situação do pagamento nunca volta atrás.
  if (anterior && ORDEM[anterior.status] >= ORDEM[pagamento.situacao]) return;
  const dados = {
    method: pagamento.meio,
    status: pagamento.situacao,
    amountCents: pagamento.valorCentavos,
    payload: pagamento.registro,
  };
  if (anterior) await tx.payment.update({ where: { id: anterior.id }, data: dados });
  else await tx.payment.create({ data: { ...chave, orderId: pedido.id, ...dados } });

  const itens = pedido.items.map((i) => ({ obraId: i.artworkId, quantidade: i.quantity }));
  if (pagamento.situacao === "APROVADO") await aprovar(tx, pedido, pagamento, agora);
  if (pagamento.situacao === "PENDENTE") await prorrogar(tx, pedido, itens, pagamento, agora);
  if (pagamento.situacao === "RECUSADO") await encerrar(tx, pedido, pagamento, agora);
  // Estorno ou chargeback de pedido já pago: o pedido segue na fila do admin, que precisa saber
  // antes de enviar. Tratar o pedido é do estorno administrativo (PBI-43).
  if (
    pagamento.situacao === "ESTORNADO" &&
    pedido.status !== "PENDENTE" &&
    pedido.status !== "CANCELADO"
  )
    console.error(
      "Pagamento estornado de pedido já pago: revisar antes de enviar (PBI-43)",
      pedido.number,
      pagamento.idExterno,
    );
}

async function tratar(
  idDado: string,
  idEvento: string,
  gateway: ConsultaPagamento,
  agora: Date,
): Promise<RespostaNotificacao> {
  const resposta = await gateway.consultarPagamento(idDado);
  // Aviso de teste do painel, ou de pagamento de outra conta: reenviar não ajuda.
  if (resposta === null) {
    console.error("Pagamento inexistente na API do Mercado Pago", idDado);
    return { status: 200 };
  }
  const lido = lerPagamento(resposta);
  if (!lido.ok) {
    // Disputa aberta e afins não mudam o pedido; reenviar não ajuda.
    if (lido.erro === "situacao_ignorada") return { status: 200 };
    // Meio novo no Checkout Pro: não grava como outro meio; o reenvio dá tempo de ajustar o Kolô.
    if (lido.erro === "meio_desconhecido")
      console.error("Pagamento com meio que o Kolô não conhece", idDado, lido.tipo);
    else console.error("Resposta inesperada da API de pagamentos", idDado);
    return { status: 500 };
  }
  // Pagamento de outra integração da conta, ou de pedido apagado: reenviar não ajuda.
  const dono = lido.dados.numeroPedido
    ? await obterPrisma().order.findUnique({
        where: { number: lido.dados.numeroPedido },
        select: { id: true, userId: true },
      })
    : null;
  if (!dono) {
    console.error("Pagamento sem pedido no Kolô", lido.dados.idExterno);
    return { status: 200 };
  }
  await obterPrisma().$transaction((tx) => aplicar(tx, lido.dados, dono, idEvento, agora));
  return { status: 200 };
}

// RF14/RNF11: Route Handler do Mercado Pago. Responde 401 sem assinatura válida, 200 quando o
// aviso foi tratado e 500 quando vale o Mercado Pago reenviar.
export async function processarNotificacao(
  requisicao: RequisicaoNotificacao,
  opcoes: OpcoesNotificacao,
): Promise<RespostaNotificacao> {
  const agora = opcoes.agora ?? new Date();
  const parametros = new URL(requisicao.url).searchParams;
  const idDado = parametros.get("data.id");
  // IPN (formato antigo, ?topic=&id=) não tem assinatura verificável: só confirma o recebimento,
  // para não ser reenviado; quem muda o pedido é o aviso assinado de Webhooks.
  if (!idDado && parametros.has("topic")) return { status: 200 };
  const assinada = assinaturaValida({
    assinatura: requisicao.cabecalhos.get("x-signature"),
    idRequisicao: requisicao.cabecalhos.get("x-request-id"),
    idDado,
    segredo: opcoes.segredo,
  });
  if (!assinada || !idDado) return { status: 401 };
  const corpo = schemaCorpo.safeParse(await requisicao.lerCorpo());
  const aviso = corpo.success ? corpo.data : {};
  // Só avisos de pagamento mudam o pedido; os demais (merchant_order etc.) só confirmam o recebimento.
  const tipo = parametros.get("type") ?? aviso.type;
  if (tipo !== "payment") return { status: 200 };
  // RNF11: o id do aviso se repete nos reenvios. Sem ele, cada requisição é um evento; a
  // idempotência continua pelo pagamento (linha única e situação que não volta atrás).
  const idAviso = aviso.id ?? requisicao.cabecalhos.get("x-request-id") ?? randomUUID();
  const idEvento = `${PROVEDOR}:${idAviso}`;

  try {
    return await tratar(idDado, idEvento, opcoes.gateway, agora);
  } catch (erro) {
    // API fora, tempo esgotado, deadlock (40P01) ou banco fora: nada foi gravado, e o Mercado
    // Pago reenvia. Só o tipo e o status HTTP: a mensagem pode trazer dados da conta.
    const status =
      erro instanceof Error && "status" in erro && typeof erro.status === "number"
        ? erro.status
        : null;
    console.error(
      "Falha ao processar o aviso do Mercado Pago",
      erro instanceof Error ? erro.name : "erro desconhecido",
      status,
    );
    return { status: 500 };
  }
}

import { z } from "zod";
import type { Prisma } from "../../../generated/prisma/client";
import { deSaoPauloParaUtc, paraHorarioSaoPaulo, somarDias } from "../../lib/fuso";
import { obterPrisma } from "../../lib/prisma";
import { equipeDaRequisicao, executar } from "./agenda";
import { inicioDaSemana } from "./agenda-regras";

type Situacao = "AGENDADO" | "CANCELADO" | "CONCLUIDO";

export type HorarioAgenda = {
  id: string;
  codigo: string;
  artistaId: string;
  artistaNome: string;
  nomeContato: string;
  telefoneContato: string;
  emailCliente: string | null;
  // "AAAA-MM-DDTHH:MM" em São Paulo (RN09), pronto para o datetime-local da edição.
  inicio: string;
  fim: string;
  situacao: Situacao;
  estiloId: string | null;
  estiloNome: string | null;
  tamanhoId: string | null;
  tamanhoNome: string | null;
  regiaoCorpo: string | null;
  observacoes: string | null;
};

export type Opcao = { id: string; nome: string };

export type AgendaDaSemana = {
  papel: "ADMIN" | "ARTISTA";
  // Agenda exibida: a do próprio artista, ou o filtro do admin (null = todos).
  artistaId: string | null;
  // Só para o admin, que escolhe o artista; o artista recebe [].
  artistas: Opcao[];
  semana: { inicio: string; fim: string; anterior: string; proxima: string };
  // Segunda a domingo, sempre os 7 dias, com os horários em ordem.
  dias: { data: string; horarios: HorarioAgenda[] }[];
  opcoes: { estilos: Opcao[]; tamanhos: Opcao[] };
};

// RF22/RN09/RN10: a semana (segunda a domingo em São Paulo) da agenda. O artista vê só a dele,
// mesmo pedindo outra; o admin vê todas ou filtra por artista. Inclui cancelados e concluídos.
export function lerAgenda(cabecalhos: Headers, filtro: { semana?: unknown; artista?: unknown }) {
  return executar(async (): Promise<AgendaDaSemana> => {
    const equipe = await equipeDaRequisicao(cabecalhos);
    const prisma = obterPrisma();

    let inicio = inicioDaSemana(typeof filtro.semana === "string" ? filtro.semana : undefined);
    if (!deSaoPauloParaUtc(`${inicio}T00:00`)) inicio = inicioDaSemana(undefined);
    const proxima = somarDias(inicio, 7);
    const de = deSaoPauloParaUtc(`${inicio}T00:00`) ?? new Date();
    const ate = deSaoPauloParaUtc(`${proxima}T00:00`) ?? new Date();

    const artistas =
      equipe.papel === "ADMIN"
        ? (
            await prisma.artist.findMany({
              where: { user: { deletedAt: null } },
              include: { user: true },
              orderBy: { user: { name: "asc" } },
            })
          ).map((a) => ({ id: a.id, nome: a.user.name }))
        : [];
    const pedido = z.uuid().safeParse(filtro.artista);
    const artistaId =
      equipe.papel === "ARTISTA"
        ? equipe.artistaId
        : pedido.success && artistas.some((a) => a.id === pedido.data.toLowerCase())
          ? pedido.data.toLowerCase()
          : null;

    const [horarios, estilos, tamanhos] = await Promise.all([
      prisma.appointment.findMany({
        where: {
          deletedAt: null,
          startsAt: { gte: de, lt: ate },
          ...(artistaId ? { artistId: artistaId } : {}),
        },
        include: {
          artist: { include: { user: true } },
          user: true,
          tattooStyle: true,
          sizeTier: true,
        },
        orderBy: [{ startsAt: "asc" }, { id: "asc" }],
      }),
      prisma.tattooStyle.findMany({ orderBy: { name: "asc" } }),
      prisma.sizeTier.findMany({ orderBy: { order: "asc" } }),
    ]);

    const dias = Array.from({ length: 7 }, (_, i) => ({
      data: somarDias(inicio, i),
      horarios: [] as HorarioAgenda[],
    }));
    for (const h of horarios) {
      const inicioLocal = paraHorarioSaoPaulo(h.startsAt);
      dias
        .find((d) => d.data === inicioLocal.slice(0, 10))
        ?.horarios.push({
          id: h.id,
          codigo: h.code,
          artistaId: h.artistId,
          artistaNome: h.artist.user.name,
          nomeContato: h.contactName,
          telefoneContato: h.contactPhone,
          emailCliente: h.user?.email ?? null,
          inicio: inicioLocal,
          fim: paraHorarioSaoPaulo(h.endsAt),
          situacao: h.status,
          estiloId: h.tattooStyleId,
          estiloNome: h.tattooStyle?.name ?? null,
          tamanhoId: h.sizeTierId,
          tamanhoNome: h.sizeTier?.name ?? null,
          regiaoCorpo: h.bodyRegion,
          observacoes: h.description,
        });
    }

    return {
      papel: equipe.papel,
      artistaId,
      artistas,
      semana: { inicio, fim: somarDias(inicio, 6), anterior: somarDias(inicio, -7), proxima },
      dias,
      opcoes: {
        estilos: estilos.map((e) => ({ id: e.id, nome: e.name })),
        tamanhos: tamanhos.map((t) => ({ id: t.id, nome: t.name })),
      },
    };
  });
}

export type HorarioProximo = {
  codigo: string;
  // "AAAA-MM-DDTHH:MM" em São Paulo (RN09).
  inicio: string;
  fim: string;
  artista: string;
  contato: string;
};

const SETE_DIAS_MS = 7 * 24 * 60 * 60 * 1000;

// RF32 (PBI-48): horários AGENDADO que começam de agora até 7 dias depois, de todos os artistas,
// para o painel do admin. Roda na transação de quem chama, que já passou pelo comoAdmin: esta
// função não confere permissão sozinha.
export async function proximosHorarios(
  tx: Prisma.TransactionClient,
  agora: Date,
): Promise<HorarioProximo[]> {
  const horarios = await tx.appointment.findMany({
    where: {
      deletedAt: null,
      status: "AGENDADO",
      startsAt: { gte: agora, lt: new Date(agora.getTime() + SETE_DIAS_MS) },
    },
    include: { artist: { include: { user: true } } },
    orderBy: [{ startsAt: "asc" }, { id: "asc" }],
  });
  return horarios.map((h) => ({
    codigo: h.code,
    inicio: paraHorarioSaoPaulo(h.startsAt),
    fim: paraHorarioSaoPaulo(h.endsAt),
    artista: h.artist.user.name,
    contato: h.contactName,
  }));
}
